"use strict";(self.webpackChunkvipzhicheng_com=self.webpackChunkvipzhicheng_com||[]).push([["5372"],{78179:function(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2025/04/15/TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","metadata":{"permalink":"/transblog/2025/04/15/TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","source":"@site/blog-translated/2025/04-15-TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357.md","title":"TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","description":"- \u539F\u6587\u94FE\u63A5\uFF1A https://github.com/sindresorhus/typescript-definition-style-guide/blob/main/readme.md?plain=1","date":"2025-04-15T12:00:00.000Z","tags":[{"inline":true,"label":"TypeScript","permalink":"/transblog/tags/type-script"}],"readingTime":23.12,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","date":"2025-04-15T12:00:00.000Z","tags":["TypeScript"]},"unlisted":false,"nextItem":{"title":"\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","permalink":"/transblog/2025/04/05/\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357"}},"content":"> - \u539F\u6587\u94FE\u63A5\uFF1A https://github.com/sindresorhus/typescript-definition-style-guide/blob/main/readme.md?plain=1\\n> - \u673A\u5668\u7FFB\u8BD1\uFF1A Gemini 2.5 Pro Preview\\n> - \u63D0\u793A\u8BCD\uFF1A \u7FFB\u8BD1\u4EE5\u4E0B\u6587\u6863\uFF0C\u5E76\u4E14\u7ED3\u5408\u4F60\u7684\u524D\u7AEF\u5F00\u53D1\u4E13\u4E1A\u77E5\u8BC6\u8865\u5145\u76F8\u5173\u7684\u77E5\u8BC6\u70B9\u8BF4\u660E\uFF0C\u5BF9\u6587\u7AE0\u5185\u5BB9\u8FDB\u884C\u7ED3\u6784\u5316\uFF0C\u4EE5 Markdown \u683C\u5F0F\u8FD4\u56DE\uFF0C\u6587\u5B57\u98CE\u683C\u662F\u6280\u672F\u535A\u5BA2\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n# TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357 (\u589E\u5F3A\u7248)\\n\\n\u672C\u6307\u5357\u5047\u8BBE\u4F60\u7684 npm \u5305\u662F\u539F\u751F ES Module (ESM) \u683C\u5F0F\u3002\u7F16\u5199\u548C\u7EF4\u62A4\u826F\u597D\u7684 TypeScript \u7C7B\u578B\u5B9A\u4E49 (`.d.ts` \u6587\u4EF6) \u5BF9\u4E8E\u5E93\u7684\u5F00\u53D1\u8005\u548C\u4F7F\u7528\u8005\u90FD\u81F3\u5173\u91CD\u8981\u3002\u5B83\u4E0D\u4EC5\u80FD\u63D0\u4F9B\u5F3A\u5927\u7684\u4EE3\u7801\u63D0\u793A\u3001\u81EA\u52A8\u8865\u5168\u548C\u7F16\u8BD1\u65F6\u7C7B\u578B\u68C0\u67E5\uFF0C\u8FD8\u80FD\u4F5C\u4E3A\u4E00\u79CD\u7CBE\u786E\u7684 API \u6587\u6863\u5F62\u5F0F\uFF0C\u663E\u8457\u63D0\u5347\u5F00\u53D1\u4F53\u9A8C (DX) \u548C\u4EE3\u7801\u5065\u58EE\u6027\u3002\\n\\n## \u6838\u5FC3\u6E05\u5355 (Core Checklist)\\n\\n\u5728\u4E3A\u4F60\u7684 npm \u5305\u6DFB\u52A0\u6216\u66F4\u65B0 TypeScript \u7C7B\u578B\u5B9A\u4E49\u65F6\uFF0C\u8BF7\u9075\u5FAA\u4EE5\u4E0B\u6838\u5FC3\u539F\u5219\uFF1A\\n\\n1.  **\u4EE3\u7801\u98CE\u683C**:\\n    - \u4F7F\u7528 **Tab** \u8FDB\u884C\u7F29\u8FDB\u3002\\n    - \u4F7F\u7528 **\u5206\u53F7** (`;`) \u7ED3\u675F\u8BED\u53E5\u3002\\n    - _\u8865\u5145: \u4FDD\u6301\u4E00\u81F4\u7684\u4EE3\u7801\u98CE\u683C\u6709\u52A9\u4E8E\u56E2\u961F\u534F\u4F5C\u548C\u4EE3\u7801\u5E93\u7684\u53EF\u7EF4\u62A4\u6027\u3002\u9009\u62E9 Tab \u8FD8\u662F\u7A7A\u683C\u3001\u662F\u5426\u4F7F\u7528\u5206\u53F7\u867D\u7136\u6709\u4E89\u8BAE\uFF0C\u4F46\u5173\u952E\u662F\u9075\u5FAA\u9879\u76EE\u6216\u56E2\u961F\u7684\u7EDF\u4E00\u89C4\u8303\u3002_\\n2.  **TypeScript \u7248\u672C**: \u7C7B\u578B\u5B9A\u4E49\u5E94\u9488\u5BF9 **\u6700\u65B0\u7A33\u5B9A\u7248** \u7684 TypeScript \u8FDB\u884C\u7F16\u5199\u3002\\n    - _\u8865\u5145: \u5229\u7528 TypeScript \u7684\u6700\u65B0\u7279\u6027\u53EF\u4EE5\u7F16\u5199\u51FA\u66F4\u7CBE\u786E\u3001\u66F4\u7B80\u6D01\u7684\u7C7B\u578B\u5B9A\u4E49\uFF0C\u540C\u65F6\u786E\u4FDD\u4E0E\u6700\u65B0\u7684 TS \u5F00\u53D1\u73AF\u5883\u517C\u5BB9\u3002_\\n3.  **\u6587\u6863\u6CE8\u91CA**: \u6240\u6709\u5BFC\u51FA\u7684\u5C5E\u6027\u3001\u65B9\u6CD5\u3001\u7C7B\u578B\u7B49\u90FD\u5E94\u4F7F\u7528 [TSDoc](https://github.com/Microsoft/tsdoc) \u683C\u5F0F\u6DFB\u52A0\u6587\u6863\u6CE8\u91CA (\u8BE6\u89C1\u4E0B\u6587)\u3002\\n    - _\u8865\u5145: \u6E05\u6670\u7684\u6587\u6863\u6CE8\u91CA\u662F\u826F\u597D\u7C7B\u578B\u5B9A\u4E49\u7684\u5173\u952E\u7EC4\u6210\u90E8\u5206\uFF0CIDE \u4F1A\u5229\u7528\u8FD9\u4E9B\u6CE8\u91CA\u63D0\u4F9B\u4E30\u5BCC\u7684\u60AC\u505C\u63D0\u793A\u4FE1\u606F\u3002_\\n4.  **\u7C7B\u578B\u6D4B\u8BD5**: \u7C7B\u578B\u5B9A\u4E49\u5FC5\u987B\u7ECF\u8FC7\u6D4B\u8BD5 (\u8BE6\u89C1\u4E0B\u6587)\u3002\\n    - _\u8865\u5145: \u7C7B\u578B\u6D4B\u8BD5\u786E\u4FDD\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u80FD\u6B63\u786E\u53CD\u6620\u8FD0\u884C\u65F6\u7684\u884C\u4E3A\uFF0C\u9632\u6B62\u7C7B\u578B\u9519\u8BEF\u6216\u4E0D\u51C6\u786E\u5BFC\u81F4\u7684\u4F7F\u7528\u8005\u56F0\u60D1\u3002_\\n5.  **Node.js \u7C7B\u578B**:\\n    - \u5982\u679C\u9700\u8981\u4F7F\u7528 Node.js \u5185\u7F6E\u6A21\u5757\u7684\u7C7B\u578B (\u5982 `fs`, `http` \u7B49)\uFF0C\u8BF7\u5C06 `@types/node` \u5B89\u88C5\u4E3A **\u5F00\u53D1\u4F9D\u8D56** (`devDependencies`)\u3002\\n    - **\u4E0D\u8981** \u5728\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u9876\u90E8\u6DFB\u52A0 `/// <reference types=\\"node\\"/>` \u4E09\u659C\u7EBF\u6307\u4EE4\u3002\u5E94\u4F7F\u7528 ES Module \u7684 `import` \u8BED\u6CD5\u5BFC\u5165\u6240\u9700\u7C7B\u578B\u3002\\n    - _\u8865\u5145: \u5C06 `@types/node` \u4F5C\u4E3A `devDependency` \u662F\u56E0\u4E3A\u7C7B\u578B\u68C0\u67E5\u53EA\u5728\u5F00\u53D1\u9636\u6BB5\u9700\u8981\u3002\u907F\u514D\u4E09\u659C\u7EBF\u6307\u4EE4\u6709\u52A9\u4E8E\u4FDD\u6301\u4EE3\u7801\u7684\u6A21\u5757\u5316\u548C\u6E05\u6670\u6027\uFF0C`import` \u8BED\u6CD5\u662F\u73B0\u4EE3 JS/TS \u7684\u6807\u51C6\u3002_\\n6.  **\u7B2C\u4E09\u65B9\u5E93\u7C7B\u578B**:\\n    - \u5982\u679C\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u4F9D\u8D56\u4E86\u5176\u4ED6\u7B2C\u4E09\u65B9\u5E93\u7684\u7C7B\u578B (\u901A\u5E38\u5728 `@types/*` \u547D\u540D\u7A7A\u95F4\u4E0B)\uFF0C\u8FD9\u4E9B\u7C7B\u578B\u5305\u5FC5\u987B\u4F5C\u4E3A **\u76F4\u63A5\u4F9D\u8D56** (`dependencies`) \u5B89\u88C5\u3002\\n    - \u540C\u6837\uFF0C\u4F7F\u7528 `import` \u8BED\u53E5\u5BFC\u5165\u7C7B\u578B\uFF0C**\u4E0D\u8981** \u4F7F\u7528\u4E09\u659C\u7EBF\u6307\u4EE4\u3002\\n    - _\u8865\u5145: \u5982\u679C\u4F60\u7684 `.d.ts` \u6587\u4EF6\u5BFC\u51FA\u7684\u7C7B\u578B\u7B7E\u540D\u4E2D\u5305\u542B\u4E86\u6765\u81EA `@types/some-lib` \u7684\u7C7B\u578B\uFF0C\u90A3\u4E48\u4F7F\u7528\u8005\u5728\u5B89\u88C5\u4F60\u7684\u5305\u65F6\uFF0C\u4E5F\u9700\u8981\u8FD9\u4E2A\u7C7B\u578B\u4FE1\u606F\u624D\u80FD\u6B63\u786E\u8FDB\u884C\u7C7B\u578B\u68C0\u67E5\u3002\u56E0\u6B64\uFF0C\u8FD9\u4E9B\u7C7B\u578B\u5305\u662F\u516C\u5171 API \u7684\u4E00\u90E8\u5206\uFF0C\u5E94\u4F5C\u4E3A `dependencies`\u3002_\\n7.  **\u907F\u514D\u5E38\u89C1\u9519\u8BEF**: \u786E\u4FDD\u4F60\u6CA1\u6709\u72AF [DefinitelyTyped \u5E38\u89C1\u9519\u8BEF\u5217\u8868](https://github.com/DefinitelyTyped/DefinitelyTyped/#common-mistakes) \u4E2D\u63D0\u5230\u7684\u95EE\u9898\u3002\\n8.  **\u9ED8\u8BA4\u5BFC\u51FA**: \u5BF9\u4E8E\u5177\u6709\u9ED8\u8BA4\u5BFC\u51FA\u7684\u5305\uFF0C\u4F7F\u7528 `export default function foo(\u2026)` \u6216 `export default class Bar {\u2026}` \u7B49\u6807\u51C6\u8BED\u6CD5\u3002\\n    - _\u8865\u5145: \u8FD9\u786E\u4FDD\u4E86\u4E0E ES Module \u7684 `import defaultMember from \'package\'` \u8BED\u6CD5\u517C\u5BB9\u3002_\\n9.  **\u7981\u6B62 `namespace`**: \u4E0D\u8981\u4F7F\u7528 `namespace` (\u6216\u65E7\u7684 `module`) \u5173\u952E\u5B57\u6765\u7EC4\u7EC7\u7C7B\u578B\u3002\\n    - _\u8865\u5145: ES Module \u63D0\u4F9B\u4E86\u6807\u51C6\u7684\u6A21\u5757\u5316\u673A\u5236\uFF0C`namespace` \u662F\u65E7\u65F6\u4EE3\u7684\u4EA7\u7269\uFF0C\u5728\u73B0\u4EE3 TS \u5F00\u53D1\u4E2D\u5E94\u907F\u514D\u4F7F\u7528\uFF0C\u4EE5\u9632\u547D\u540D\u51B2\u7A81\u548C\u589E\u52A0\u7406\u89E3\u8D1F\u62C5\u3002_\\n10. **\u9075\u5FAA\u8D21\u732E\u6D41\u7A0B** (\u5982\u679C\u9002\u7528\uFF0C\u4F8B\u5982\u5411 Sindre Sorhus \u7684\u9879\u76EE\u8D21\u732E):\\n    - Pull Request \u7684\u6807\u9898\u5E94\u4E3A `Add TypeScript definition` (\u8BF7\u76F4\u63A5\u590D\u5236\u7C98\u8D34\uFF0C\u786E\u4FDD\u65E0\u8BEF)\u3002\\n    - \u79EF\u6781\u5E2E\u52A9\u5BA1\u67E5\u5176\u4ED6\u6DFB\u52A0\u7C7B\u578B\u5B9A\u4E49\u7684 [Pull Requests](https://github.com/search?q=user%3Asindresorhus+is%3Apr+is%3Aopen+%22Add+TypeScript+definition%22&type=Issues)\u3002\\n\\n\u53EF\u4EE5\u53C2\u8003\u4EE5\u4E0B\u4F18\u79C0\u5B9E\u8DF5\u6848\u4F8B\uFF1A\\n\\n- [sindresorhus/filled-array \u7684\u7C7B\u578B\u5B9A\u4E49\u63D0\u4EA4](https://github.com/sindresorhus/filled-array/commit/aae7539cb32f163cb063499664b012d0b04b3104) (\u5305\u542B\u6D4B\u8BD5\u96C6\u6210)\\n- [sindresorhus/write-json-file \u7684 index.d.ts](https://github.com/sindresorhus/write-json-file/blob/main/index.d.ts)\\n- [sindresorhus/delay \u7684 index.d.ts](https://github.com/sindresorhus/delay/blob/main/index.d.ts)\\n\\n## `package.json` \u914D\u7F6E\\n\\n\u6B63\u786E\u914D\u7F6E `package.json` \u662F\u8BA9 TypeScript \u548C\u5F00\u53D1\u5DE5\u5177\u627E\u5230\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u7684\u5173\u952E\u3002\\n\\n1.  **`types` \u5B57\u6BB5**:\\n    - \u4F7F\u7528 `\\"types\\"` \u5B57\u6BB5\u6307\u5B9A\u4E3B\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u7684\u8DEF\u5F84\uFF0C**\u4E0D\u8981** \u4F7F\u7528 `\\"typings\\"`\u3002\\n    - _\u8865\u5145: `\\"types\\"` \u662F TypeScript \u5B98\u65B9\u63A8\u8350\u4E14\u66F4\u73B0\u4EE3\u7684\u5B57\u6BB5\u540D\u3002_\\n    - \u8BE5\u5B57\u6BB5\u5E94\u653E\u7F6E\u5728\u6240\u6709\u5B98\u65B9 `package.json` \u5C5E\u6027 (\u5982 `name`, `version`, `main`, `module`, `exports`) \u4E4B\u540E\uFF0C\u4F46\u5728\u81EA\u5B9A\u4E49\u5C5E\u6027\u4E4B\u524D\u3002\u63A8\u8350\u653E\u5728 `\\"dependencies\\"` \u548C/\u6216 `\\"devDependencies\\"` \u4E4B\u540E\u3002\\n2.  **\u5165\u53E3\u6587\u4EF6\u4E0E\u7C7B\u578B\u6587\u4EF6\u547D\u540D**:\\n    - \u5982\u679C\u5305\u7684\u5165\u53E3\u6587\u4EF6\u662F `index.js` (\u6216 `index.mjs` \u7B49)\uFF0C\u5219\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u5E94\u547D\u540D\u4E3A `index.d.ts` \u5E76\u653E\u7F6E\u5728 **\u5305\u7684\u6839\u76EE\u5F55**\u3002\\n    - \u5728\u8FD9\u79CD\u60C5\u51B5\u4E0B\uFF0C\u4F60 **\u4E0D\u9700\u8981** \u5728 `package.json` \u4E2D\u6DFB\u52A0 `\\"types\\"` \u5B57\u6BB5\uFF0CTypeScript \u4F1A\u6839\u636E `main` \u6216 `exports` \u5B57\u6BB5\u81EA\u52A8\u63A8\u65AD\u5E76\u627E\u5230\u540C\u540D\u7684 `.d.ts` \u6587\u4EF6\u3002\\n    - _\u8865\u5145: \u5229\u7528 TypeScript \u7684\u9ED8\u8BA4\u63A8\u65AD\u673A\u5236\u53EF\u4EE5\u7B80\u5316\u914D\u7F6E\u3002\u4F46\u5982\u679C\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u4E0D\u5728\u6839\u76EE\u5F55\u6216\u540D\u79F0\u4E0E\u5165\u53E3\u6587\u4EF6\u4E0D\u540C\uFF0C\u5219\u5FC5\u987B\u4F7F\u7528 `\\"types\\"` \u5B57\u6BB5\u663E\u5F0F\u6307\u5B9A\u3002_\\n3.  **`files` \u5B57\u6BB5**:\\n    - \u786E\u4FDD\u5C06\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6 (\u5982 `index.d.ts` \u6216 `dist/types/` \u76EE\u5F55) \u6DFB\u52A0\u5230 `package.json` \u7684 `\\"files\\"` \u6570\u7EC4\u4E2D\u3002\\n    - _\u8865\u5145: `\\"files\\"` \u5B57\u6BB5\u63A7\u5236\u54EA\u4E9B\u6587\u4EF6\u4F1A\u88AB\u5305\u542B\u5728\u6700\u7EC8\u53D1\u5E03\u7684 npm \u5305\u91CC\u3002\u5FD8\u8BB0\u6DFB\u52A0\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u4F1A\u5BFC\u81F4\u4F7F\u7528\u8005\u5B89\u88C5\u4E86\u4F60\u7684\u5305\u5374\u65E0\u6CD5\u83B7\u5F97\u7C7B\u578B\u652F\u6301\u3002_\\n\\n## \u7C7B\u578B\u5B9A\u4E49\u6700\u4F73\u5B9E\u8DF5 (Type Definition Best Practices)\\n\\n\u7F16\u5199\u6E05\u6670\u3001\u51C6\u786E\u3001\u6613\u4E8E\u4F7F\u7528\u7684\u7C7B\u578B\u662F\u6211\u4EEC\u7684\u76EE\u6807\u3002\\n\\n### \u7C7B\u578B\u547D\u540D\u4E0E\u98CE\u683C\\n\\n1.  **\u7C7B\u578B\u547D\u540D**:\\n    - \u7C7B\u578B\u540D\u79F0\u4E0D\u5E94\u5305\u542B\u547D\u540D\u7A7A\u95F4\u524D\u7F00\uFF0C\u4F8B\u5982\u4F7F\u7528 `type Options {}` \u800C\u4E0D\u662F `type FooOptions {}`\uFF0C\u9664\u975E\u786E\u5B9E\u5B58\u5728\u591A\u4E2A\u540C\u540D `Options` \u63A5\u53E3\u9700\u8981\u533A\u5206\u3002\\n    - \u907F\u514D\u4F7F\u7528\u7F29\u5199\uFF1A\u51FD\u6570\u53C2\u6570\u3001\u53D8\u91CF\u548C\u7C7B\u578B\u540D\u5E94\u4F7F\u7528\u5B8C\u6574\u5355\u8BCD\uFF0C\u5982 `function process(options: Options)` \u800C\u4E0D\u662F `function process(opts: Opts)`\u3002\\n    - \u63A5\u53E3\u540D\u79F0 **\u4E0D\u8981** \u52A0 `I` \u524D\u7F00\uFF1A\u4F7F\u7528 `Options` \u800C\u4E0D\u662F `IOptions`\u3002\\n    - _\u8865\u5145: \u8FD9\u4E9B\u7EA6\u5B9A\u63D0\u9AD8\u4E86\u4EE3\u7801\u7684\u53EF\u8BFB\u6027\u548C\u4E00\u81F4\u6027\u3002`I` \u524D\u7F00\u662F\u67D0\u4E9B\u8BED\u8A00 (\u5982 C#) \u7684\u4E60\u60EF\uFF0C\u4F46\u5728 TypeScript \u793E\u533A\u5DF2\u4E0D\u518D\u63A8\u8350\u3002_\\n2.  **\u6570\u7EC4\u7C7B\u578B**:\\n    - \u4F7F\u7528\u6570\u7EC4\u7C7B\u578B\u7B80\u5199\uFF1A`number[]` \u800C\u4E0D\u662F `Array<number>`\u3002\\n    - \u4F7F\u7528 `readonly` \u4FEE\u9970\u7B26\u8868\u793A\u53EA\u8BFB\u6570\u7EC4\uFF1A`readonly number[]` \u800C\u4E0D\u662F `ReadonlyArray<number>`\u3002\\n    - _\u8865\u5145: \u7B80\u5199\u5F62\u5F0F\u66F4\u7B80\u6D01\uFF0C`readonly T[]` \u662F TS \u5185\u7F6E\u7684\u3001\u66F4\u63A8\u8350\u7684\u53EA\u8BFB\u6570\u7EC4\u8868\u793A\u6CD5\u3002_\\n3.  **\u6CDB\u578B\u53D8\u91CF**:\\n    - \u5F53\u4E00\u4E2A\u65B9\u6CD5\u6216\u7C7B\u578B\u6709\u591A\u4E2A\u6CDB\u578B\u7C7B\u578B\u53D8\u91CF\u65F6\uFF0C\u5E94\u4F7F\u7528\u5177\u6709\u63CF\u8FF0\u6027\u7684\u540D\u79F0\uFF1A`type Mapper<Element, NewElement> = \u2026` \u800C\u4E0D\u662F `type Mapper<T, U> = \u2026`\u3002\\n    - _\u8865\u5145: \u867D\u7136 `T`, `U`, `K`, `V` \u662F\u5E38\u89C1\u7684\u6CDB\u578B\u53D8\u91CF\u540D\uFF0C\u4F46\u5728\u6709\u591A\u4E2A\u6CDB\u578B\u53C2\u6570\u65F6\uFF0C\u63CF\u8FF0\u6027\u540D\u79F0\u80FD\u663E\u8457\u63D0\u9AD8\u590D\u6742\u7C7B\u578B\u7684\u53EF\u8BFB\u6027\u3002_\\n4.  **\u4EE3\u7801\u683C\u5F0F**:\\n    - \u5BFC\u5165\u3001\u89E3\u6784\u8D4B\u503C\u548C\u5BF9\u8C61\u5B57\u9762\u91CF\u4E2D\uFF0C\u6807\u8BC6\u7B26\u5468\u56F4 **\u4E0D** \u5E94\u6709\u7A7A\u683C\uFF1A\u4F7F\u7528 `{foo}` \u800C\u4E0D\u662F `{ foo }`\u3002\\n    - _\u8865\u5145: \u8FD9\u662F\u8BB8\u591A\u6D41\u884C\u683C\u5F0F\u5316\u5DE5\u5177 (\u5982 Prettier) \u7684\u9ED8\u8BA4\u884C\u4E3A\uFF0C\u4FDD\u6301\u4E00\u81F4\u6027\u3002_\\n\\n### \u7C7B\u578B\u7CBE\u786E\u6027\\n\\n1.  **`unknown` vs `any`**:\\n    - \u5C3D\u53EF\u80FD\u4F7F\u7528 [`unknown` \u7C7B\u578B](https://www.typescriptlang.org/docs/handbook/release-notes/typescript-3-0.html#new-unknown-top-type)\u66FF\u4EE3 `any`\u3002\\n    - _\u8865\u5145: `any` \u4F1A\u5B8C\u5168\u7ED5\u8FC7\u7C7B\u578B\u68C0\u67E5\uFF0C\u662F\u7C7B\u578B\u5B89\u5168\u7684\u201C\u540E\u95E8\u201D\u3002`unknown` \u5219\u8868\u793A\u201C\u4EFB\u4F55\u7C7B\u578B\u90FD\u53EF\u4EE5\u8D4B\u7ED9\u6211\uFF0C\u4F46\u6211\u662F\u7C7B\u578B\u5B89\u5168\u7684\uFF0C\u4F60\u4E0D\u80FD\u76F4\u63A5\u64CD\u4F5C\u6211\uFF0C\u5FC5\u987B\u5148\u8FDB\u884C\u7C7B\u578B\u68C0\u67E5\u6216\u65AD\u8A00\u201D\u3002\u4F7F\u7528 `unknown` \u80FD\u5728\u4FDD\u6301\u7075\u6D3B\u6027\u7684\u540C\u65F6\u5F3A\u5236\u8FDB\u884C\u7C7B\u578B\u4FDD\u62A4\uFF0C\u63D0\u9AD8\u4EE3\u7801\u7684\u5065\u58EE\u6027\u3002_\\n2.  **\u907F\u514D\u5BBD\u6CDB\u7C7B\u578B**:\\n    - \u4E0D\u8981\u4F7F\u7528\u8FC7\u4E8E\u5BBD\u6CDB\u7684\u7C7B\u578B\uFF0C\u5982 `object` \u6216 `Function`\u3002\u5E94\u4F7F\u7528\u66F4\u5177\u4F53\u7684\u7C7B\u578B\u7B7E\u540D\uFF0C\u4F8B\u5982 `Record<string, number>` (\u8868\u793A\u952E\u4E3A\u5B57\u7B26\u4E32\u3001\u503C\u4E3A\u6570\u5B57\u7684\u5BF9\u8C61) \u6216 `(input: string) => boolean;` (\u8868\u793A\u63A5\u53D7\u4E00\u4E2A\u5B57\u7B26\u4E32\u53C2\u6570\u5E76\u8FD4\u56DE\u5E03\u5C14\u503C\u7684\u51FD\u6570)\u3002\\n    - _\u8865\u5145: `object` \u7C7B\u578B\u51E0\u4E4E\u4E0D\u63D0\u4F9B\u4EFB\u4F55\u6709\u7528\u7684\u7C7B\u578B\u4FE1\u606F\u3002`Function` \u7C7B\u578B\u540C\u6837\u65E0\u6CD5\u63CF\u8FF0\u51FD\u6570\u7684\u53C2\u6570\u548C\u8FD4\u56DE\u503C\u3002\u4F7F\u7528\u5177\u4F53\u7684\u7C7B\u578B\u7B7E\u540D\u80FD\u63D0\u4F9B\u66F4\u5F3A\u7684\u7C7B\u578B\u7EA6\u675F\u548C\u66F4\u597D\u7684\u5F00\u53D1\u4F53\u9A8C\u3002_\\n3.  **\u5BF9\u8C61\u7D22\u5F15\u7B7E\u540D**:\\n    - \u5BF9\u4E8E\u63A5\u53D7\u5177\u6709\u5B57\u7B26\u4E32\u7D22\u5F15\u7C7B\u578B\u7684\u5BF9\u8C61\u4F5C\u4E3A\u53C2\u6570\u65F6\uFF0C\u53EF\u4EE5\u4F7F\u7528 `Record<string, any>`\u3002\\n    - \u5BF9\u4E8E\u8FD4\u56DE\u6B64\u7C7B\u5BF9\u8C61\u65F6\uFF0C\u5E94\u4F7F\u7528 `Record<string, unknown>`\u3002\\n    - \u539F\u56E0\uFF1ATypeScript \u5BF9 `Record<string, any>` \u6709\u7279\u6B8A\u5904\u7406\uFF1A**\u4EFB\u4F55\u5BF9\u8C61\u7C7B\u578B\u90FD\u53EF\u4EE5\u8D4B\u503C\u7ED9\u5B83**\u3002\u8FD9\u4F7F\u5F97\u5B83\u5728\u4F5C\u4E3A\u51FD\u6570\u53C2\u6570\u65F6\u66F4\u5177\u7075\u6D3B\u6027\uFF08\u5C3D\u7BA1\u635F\u5931\u4E86\u4E00\u4E9B\u7C7B\u578B\u5B89\u5168\uFF09\u3002\u800C\u8FD4\u56DE `Record<string, unknown>` \u5219\u66F4\u5B89\u5168\uFF0C\u5F3A\u5236\u4F7F\u7528\u8005\u5728\u4F7F\u7528\u8FD4\u56DE\u503C\u4E4B\u524D\u8FDB\u884C\u7C7B\u578B\u68C0\u67E5\u3002\\n\\n### \u5F3A\u8C03\u53EA\u8BFB\u6027 (Prefer Read-only Values)\\n\\n\u5F53\u67D0\u4E2A\u503C\uFF08\u901A\u5E38\u662F\u51FD\u6570\u8FD4\u56DE\u503C\u6216\u914D\u7F6E\u9009\u9879\uFF09\u4E0D\u5E94\u8BE5\u88AB\u4FEE\u6539\u65F6\uFF0C\u660E\u786E\u5730\u5C06\u5176\u6807\u8BB0\u4E3A\u53EA\u8BFB\u3002\u719F\u6089 `readonly` \u5173\u952E\u5B57\u5728[\u5C5E\u6027](https://www.typescriptlang.org/docs/handbook/interfaces.html#readonly-properties)\u548C[\u6570\u7EC4/\u5143\u7EC4\u7C7B\u578B](https://github.com/Microsoft/TypeScript/wiki/What\'s-new-in-TypeScript#improvements-for-readonlyarray-and-readonly-tuples)\u4E2D\u7684\u5E94\u7528\u3002\u6B64\u5916\uFF0C\u8FD8\u6709\u4E00\u4E2A [`Readonly<T>` \u6620\u5C04\u7C7B\u578B](https://basarat.gitbooks.io/typescript/docs/types/readonly.html)\u53EF\u4EE5\u5C06\u4E00\u4E2A\u7C7B\u578B\u7684\u6240\u6709\u5C5E\u6027\u6807\u8BB0\u4E3A `readonly`\u3002\\n\\n**\u4E4B\u524D**:\\n\\n```ts\\ntype Point = {\\n  x: number;\\n  y: number;\\n  children: Point[];\\n};\\n```\\n\\n**\u4E4B\u540E**:\\n\\n```ts\\ntype Point = {\\n  readonly x: number;\\n  readonly y: number;\\n  readonly children: readonly Point[];\\n};\\n\\n// \u6216\u8005\u5BF9\u4E8E\u6574\u4E2A\u5BF9\u8C61\u53CA\u5176\u5D4C\u5957\u5C5E\u6027\\ntype DeepReadonlyPoint = Readonly<{\\n  x: number;\\n  y: number;\\n  children: ReadonlyArray<DeepReadonlyPoint>; // \u6CE8\u610F\u9012\u5F52\u5E94\u7528\\n}>;\\n```\\n\\n_\u8865\u5145: \u4F7F\u7528 `readonly` \u6709\u52A9\u4E8E\u5B9E\u73B0\u4E0D\u53EF\u53D8\u6027 (Immutability)\uFF0C\u8FD9\u53EF\u4EE5\u51CF\u5C11\u526F\u4F5C\u7528\uFF0C\u4F7F\u4EE3\u7801\u72B6\u6001\u66F4\u53EF\u9884\u6D4B\uFF0C\u7279\u522B\u662F\u5728\u5904\u7406\u590D\u6742\u6570\u636E\u7ED3\u6784\u6216\u8FDB\u884C\u51FD\u6570\u5F0F\u7F16\u7A0B\u65F6\u3002_\\n\\n### \u663E\u5F0F\u5BFC\u5165\u7C7B\u578B (Import Types Explicitly)\\n\\n\u9664\u4E86 JavaScript \u5185\u7F6E\u7C7B\u578B (\u5982 `string`, `Promise`) \u6216\u65E0\u6CD5\u901A\u8FC7 `import` \u5BFC\u5165\u7684\u5168\u5C40\u7C7B\u578B (\u4F8B\u5982\u67D0\u4E9B\u73AF\u5883\u7279\u5B9A\u7684\u5168\u5C40\u53D8\u91CF)\uFF0C\u90FD **\u4E0D\u8981** \u4F9D\u8D56\u9690\u5F0F\u7684\u5168\u5C40\u7C7B\u578B\u3002\\n\\n**\u4E4B\u524D**: (\u5047\u8BBE `Electron` \u7C7B\u578B\u88AB\u5168\u5C40\u6CE8\u5165)\\n\\n```ts\\nexport function getWindow(): Electron.BrowserWindow;\\n```\\n\\n**\u4E4B\u540E**: (\u660E\u786E\u5BFC\u5165\u6240\u9700\u7C7B\u578B)\\n\\n```ts\\nimport { BrowserWindow } from \\"electron\\"; // \u9700\u8981\u5B89\u88C5 @types/electron\\n\\nexport function getWindow(): BrowserWindow;\\n```\\n\\n_\u8865\u5145: \u663E\u5F0F\u5BFC\u5165\u4F7F\u4EE3\u7801\u7684\u4F9D\u8D56\u5173\u7CFB\u66F4\u6E05\u6670\uFF0C\u907F\u514D\u4E86\u5168\u5C40\u547D\u540D\u7A7A\u95F4\u7684\u6C61\u67D3\uFF0C\u5E76\u4E14\u66F4\u7B26\u5408 ES Module \u7684\u89C4\u8303\u3002_\\n\\n### \u53EF\u8BFB\u7684\u547D\u540D\u5BFC\u5165 (Readable Named Imports)\\n\\n\u5F53\u5BFC\u5165\u7684\u7C7B\u578B\u540D\u79F0\u53EF\u80FD\u4E0E\u5176\u4ED6\u5C40\u90E8\u53D8\u91CF\u6216\u7C7B\u578B\u51B2\u7A81\uFF0C\u6216\u8005\u540D\u79F0\u672C\u8EAB\u4E0D\u591F\u6E05\u6670\u65F6\uFF0C\u4F7F\u7528 `as` \u5173\u952E\u5B57\u8FDB\u884C\u91CD\u547D\u540D\uFF0C\u63D0\u4F9B\u4E00\u4E2A\u66F4\u5177\u53EF\u8BFB\u6027\u7684\u522B\u540D\u3002\\n\\n**\u4E4B\u524D**: (\u5982\u679C `Writable` \u5728\u5F53\u524D\u4F5C\u7528\u57DF\u53EF\u80FD\u5F15\u8D77\u6B67\u4E49)\\n\\n```ts\\nimport { Writable } from \\"node:stream\\";\\n\\nexport function createLogStream(): Writable;\\n```\\n\\n**\u4E4B\u540E**: (\u4F7F\u7528\u522B\u540D\u63D0\u9AD8\u6E05\u6670\u5EA6)\\n\\n```ts\\nimport { Writable as WritableStream } from \\"node:stream\\"; // \u9700\u8981 @types/node\\n\\nexport function createLogStream(): WritableStream;\\n```\\n\\n_\u8865\u5145: \u597D\u7684\u547D\u540D\u662F\u4EE3\u7801\u81EA\u6587\u6863\u5316\u7684\u91CD\u8981\u90E8\u5206\u3002\u5BF9\u4E8E\u6765\u81EA Node.js \u6216\u5176\u4ED6\u5E93\u7684\u901A\u7528\u540D\u79F0 (\u5982 `Stream`, `Buffer`, `EventEmitter`)\uFF0C\u6DFB\u52A0\u4E0A\u4E0B\u6587\u76F8\u5173\u7684\u540E\u7F00 (\u5982 `WritableStream`, `FileBuffer`, `MyEventEmitter`) \u901A\u5E38\u662F\u4E2A\u597D\u4E3B\u610F\u3002_\\n\\n## \u4F7F\u7528 TSDoc \u7F16\u5199\u6587\u6863\u6CE8\u91CA (Documenting with TSDoc)\\n\\n\u6240\u6709\u5BFC\u51FA\u7684\u5B9A\u4E49 (\u51FD\u6570\u3001\u7C7B\u3001\u7C7B\u578B\u3001\u63A5\u53E3\u3001\u5E38\u91CF\u7B49) \u90FD\u5E94\u4F7F\u7528 [TSDoc](https://github.com/Microsoft/tsdoc) \u6807\u51C6\u8FDB\u884C\u6587\u6863\u6CE8\u91CA\u3002\u4F60\u53EF\u4EE5\u4ECE\u9879\u76EE\u7684 `README.md` \u6587\u4EF6\u4E2D\u501F\u9274\u63CF\u8FF0\u6027\u6587\u5B57\u3002\\n\\n**\u793A\u4F8B**:\\n\\n````ts\\n/**\\n * Represents configuration options for the \'add\' function.\\n */\\nexport type Options = {\\n  /**\\n   * Allow negative numbers in the calculation.\\n   *\\n   * @default true\\n   */\\n  readonly allowNegative?: boolean;\\n\\n  /**\\n   * Specifies whether the ultimate foo feature is enabled.\\n   *\\n   * Note: Only use this feature for good, never for evil.\\n   *\\n   * @default false\\n   */\\n  readonly hasFoo?: boolean;\\n\\n  /**\\n   * The directory path where the result should be saved.\\n   *\\n   * Defaults to the user\'s downloads directory (see [https://example.com](https://example.com) for details).\\n   *\\n   * @example\\n   * ```typescript\\n   * import add from \'my-add-package\';\\n   *\\n   * add(1, 2, {saveDirectory: \'/my/awesome/dir\'});\\n   * ```\\n   */\\n  readonly saveDirectory?: string;\\n};\\n\\n/**\\n * Adds two numbers together.\\n * This function serves as a basic example for demonstrating TSDoc usage.\\n *\\n * @param x - The first number to add. Must be a finite number.\\n * @param y - The second number to add. Must be a finite number.\\n * @param options - Optional configuration for the addition process.\\n * @returns The sum of `x` and `y`.\\n *\\n * @throws {TypeError} If either x or y is not a finite number.\\n */\\nexport default function add(x: number, y: number, options?: Options): number;\\n````\\n\\n**TSDoc \u6CE8\u91CA\u89C4\u8303**:\\n\\n- \u6CE8\u91CA\u5757\u4EE5 `/**` \u5F00\u59CB\uFF0C\u4EE5 `*/` \u7ED3\u675F\u3002\\n- \u6CE8\u91CA\u5185\u5BB9 **\u4E0D\u8981** \u4EE5 `*` \u5F00\u5934\u3002\\n- \u6CE8\u91CA\u6587\u672C **\u4E0D\u8981** \u8FDB\u884C\u786C\u6362\u884C (hard-wrap)\uFF0C\u8BA9\u7F16\u8F91\u5668\u6216\u6E32\u67D3\u5DE5\u5177\u81EA\u52A8\u5904\u7406\u3002\\n- \u5728\u7C7B\u578B/\u63A5\u53E3\u7684\u5C5E\u6027\u6587\u6863\u4E4B\u95F4\u4FDD\u7559\u4E00\u4E2A\u7A7A\u884C\u3002\\n- \u53E5\u5B50\u5E94\u4EE5\u5927\u5199\u5B57\u6BCD\u5F00\u5934\uFF0C\u4EE5\u53E5\u70B9 (`.`) \u7ED3\u675F\u3002\\n- \u51FD\u6570/\u65B9\u6CD5\u7684\u4E3B\u63CF\u8FF0\u540E\u9762\u5E94\u6709\u4E00\u4E2A\u7A7A\u884C\uFF0C\u7136\u540E\u662F `@param`, `@returns` \u7B49\u6807\u7B7E\u3002\\n- \u6240\u6709\u53C2\u6570 (`@param`) \u548C\u8FD4\u56DE\u503C (`@returns`) \u90FD\u5E94\u88AB\u6587\u6863\u5316\u3002\\n- `@param` \u540E\u9762\u8DDF\u7740\u53C2\u6570\u540D\uFF0C\u7136\u540E\u662F\u4E00\u4E2A\u7834\u6298\u53F7 (`-`)\uFF0C\u6700\u540E\u662F\u53C2\u6570\u63CF\u8FF0\u3002\\n- `@param` **\u4E0D\u5E94** \u5305\u542B\u53C2\u6570\u7684\u7C7B\u578B\u4FE1\u606F (\u7C7B\u578B\u4FE1\u606F\u7531 TypeScript \u4EE3\u7801\u672C\u8EAB\u63D0\u4F9B)\u3002\\n- \u5982\u679C\u53C2\u6570\u63CF\u8FF0\u4EC5\u4EC5\u662F\u91CD\u590D\u53C2\u6570\u540D (\u4F8B\u5982 `@param options - The options object`)\uFF0C\u53EF\u4EE5\u7701\u7565\u63CF\u8FF0 (\u9664\u975E\u53C2\u6570\u540D\u672C\u8EAB\u4E0D\u591F\u6E05\u6670)\u3002\u5BF9\u4E8E\u5E38\u89C1\u7684 `options` \u53C2\u6570\uFF0C\u901A\u5E38\u4E0D\u9700\u8981\u989D\u5916\u63CF\u8FF0\u3002\\n- \u5982\u679C\u51FD\u6570\u8FD4\u56DE `void` \u6216\u5305\u88F9 `void` \u7684 Promise (\u5982 `Promise<void>`)\uFF0C\u53EF\u4EE5\u7701\u7565 `@returns` \u6807\u7B7E\u3002\\n- \u4F7F\u7528 `@returns` \u800C\u4E0D\u662F `@return`\u3002\\n- `@returns` \u7684\u63CF\u8FF0\u5E94\u6E05\u6670\u8BF4\u660E\u8FD4\u56DE\u503C\u7684\u542B\u4E49\uFF0C\u9664\u975E\u8FD4\u56DE\u503C\u7684\u7C7B\u578B\u672C\u8EAB\u5DF2\u7ECF\u8DB3\u591F\u6E05\u6670\uFF0C\u5426\u5219**\u4E0D\u8981**\u7B80\u5355\u91CD\u590D\u7C7B\u578B\u4FE1\u606F (\u4F8B\u5982\uFF0C\u5C06 `@returns A boolean of whether it was enabled.` \u6539\u8FDB\u4E3A `@returns Whether it was enabled.`)\u3002\\n- \u4F7F\u7528 `@default` \u6807\u7B7E\u8BB0\u5F55\u9009\u9879\u6216\u53C2\u6570\u7684\u9ED8\u8BA4\u503C\u3002\u7531\u4E8E\u7C7B\u578B\u5B9A\u4E49\u672C\u8EAB\u4E0D\u80FD\u6307\u5B9A\u9ED8\u8BA4\u503C\uFF0C\u8FD9\u4E2A\u6807\u7B7E\u975E\u5E38\u91CD\u8981\u3002\u5982\u679C\u9ED8\u8BA4\u503C\u9700\u8981\u6587\u5B57\u63CF\u8FF0\u800C\u4E0D\u662F\u7B80\u5355\u7684\u5B57\u9762\u91CF\uFF0C\u53EF\u4EE5\u4F7F\u7528 `Default: Some description.` \u7684\u683C\u5F0F\u3002\\n- \u5982\u679C\u5305\u542B `@example` \u6807\u7B7E\uFF0C\u5176\u4E0A\u65B9\u5E94\u6709\u4E00\u4E2A\u7A7A\u884C\u3002\u4EE3\u7801\u793A\u4F8B\u5E94\u4F7F\u7528 Markdown \u7684\u4EE3\u7801\u5757 (\u4E09\u4E2A\u53CD\u5F15\u53F7 ```) \u5305\u88F9\uFF0C\u5E76\u6700\u597D\u6307\u5B9A\u8BED\u8A00 (\u5982 `typescript`\u6216`javascript`)\u3002\\n- \u73AF\u5883\u58F0\u660E (ambient declarations, `.d.ts` \u6587\u4EF6\u4E2D\u7684\u5185\u5BB9) \u4E0D\u80FD\u6709\u9ED8\u8BA4\u53C2\u6570\u503C\u3002\u5982\u679C\u51FD\u6570\u5B9E\u73B0\u4E2D\u6709\u9ED8\u8BA4\u53C2\u6570\uFF0C\u5E94\u5728 `@param` \u7684\u63CF\u8FF0\u4E2D\u6216\u4F7F\u7528 `@default` \u6807\u7B7E\u8FDB\u884C\u8BF4\u660E\u3002\\n\\n_\u8865\u5145: \u9075\u5FAA TSDoc \u89C4\u8303\u4F7F\u5F97\u6587\u6863\u6CE8\u91CA\u80FD\u591F\u88AB\u5404\u79CD\u5DE5\u5177 (\u5982 VS Code \u7684 IntelliSense\u3001TypeDoc \u7B49\u6587\u6863\u751F\u6210\u5668) \u6B63\u786E\u89E3\u6790\u548C\u5C55\u793A\uFF0C\u6781\u5927\u5730\u63D0\u5347\u4E86\u5E93\u7684\u4F7F\u7528\u8005\u4F53\u9A8C\u3002_\\n\\n### \u4EE3\u7801\u793A\u4F8B (Code Examples in Docs)\\n\\n- \u5C3D\u53EF\u80FD\u591A\u5730\u5305\u542B\u4EE3\u7801\u793A\u4F8B\uFF0C\u53EF\u4EE5\u4ECE `README.md` \u6216\u5B9E\u9645\u7528\u4F8B\u4E2D\u63D0\u53D6\u3002\\n- \u4EE3\u7801\u793A\u4F8B\u5E94\u8BE5\u662F\u529F\u80FD\u5B8C\u6574\u7684\uFF0C\u80FD\u591F\u76F4\u63A5\u8FD0\u884C (\u6216\u7A0D\u4F5C\u4FEE\u6539\u5373\u53EF\u8FD0\u884C)\uFF0C\u5E76\u5E94\u5305\u542B\u5FC5\u8981\u7684 `import` \u8BED\u53E5\u3002\\n- _\u8865\u5145: \u597D\u7684\u4EE3\u7801\u793A\u4F8B\u662F\u5B66\u4E60\u5982\u4F55\u4F7F\u7528\u5E93\u7684\u6700\u5FEB\u65B9\u5F0F\u3002\u786E\u4FDD\u793A\u4F8B\u6E05\u6670\u3001\u51C6\u786E\u4E14\u6DB5\u76D6\u5E38\u89C1\u7528\u4F8B\u3002_\\n\\n## \u4F7F\u7528 tsd \u8FDB\u884C\u7C7B\u578B\u6D4B\u8BD5 (Testing Types with tsd)\\n\\n\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6 (`.d.ts`) \u672C\u8EAB\u4E5F\u9700\u8981\u6D4B\u8BD5\uFF01\u8FD9\u786E\u4FDD\u4E86\u7C7B\u578B\u5B9A\u4E49\u7684\u51C6\u786E\u6027\uFF0C\u80FD\u6355\u83B7\u8BF8\u5982\u7C7B\u578B\u8FC7\u4E8E\u5BBD\u6CDB\u3001\u8FC7\u7A84\u3001\u9519\u8BEF\u6216\u4E0E\u5B9E\u9645 JavaScript \u5B9E\u73B0\u4E0D\u7B26\u7B49\u95EE\u9898\u3002\u63A8\u8350\u4F7F\u7528 [`tsd`](https://github.com/SamVerschueren/tsd) \u8FD9\u4E2A\u5DE5\u5177\u6765\u8FDB\u884C\u7C7B\u578B\u6D4B\u8BD5\u3002\\n\\n**\u96C6\u6210\u793A\u4F8B**: \u67E5\u770B [sindresorhus/filled-array \u7684\u8FD9\u4E2A\u63D0\u4EA4](https://github.com/sindresorhus/filled-array/commit/aae7539cb32f163cb063499664b012d0b04b3104)\uFF0C\u4E86\u89E3\u5982\u4F55\u5C06 `tsd` \u96C6\u6210\u5230\u9879\u76EE\u4E2D (\u901A\u5E38\u662F\u5728 `package.json` \u7684 `scripts` \u4E2D\u6DFB\u52A0\u4E00\u4E2A\u6D4B\u8BD5\u547D\u4EE4\uFF0C\u5E76\u521B\u5EFA\u4E00\u4E2A\u7C7B\u578B\u6D4B\u8BD5\u6587\u4EF6)\u3002\\n\\n**\u6D4B\u8BD5\u6587\u4EF6\u793A\u4F8B**:\\n\\n```ts\\n// test/index.test-d.ts \u6216\u7C7B\u4F3C\u8DEF\u5F84\\nimport { expectType, expectError, expectAssignable } from \\"tsd\\";\\nimport delay, { type Options } from \\"../index.js\\"; // \u5047\u8BBE index.js \u662F\u5165\u53E3\\n\\n// \u6D4B\u8BD5\u6210\u529F\u6848\u4F8B (\u7C7B\u578B\u5339\u914D)\\nexpectType<Promise<void>>(delay(200));\\nexpectType<Promise<string>>(delay(200, { value: \\"\uD83E\uDD84\\" }));\\nexpectType<Promise<number>>(delay(200, { value: 0 }));\\n\\n// \u6D4B\u8BD5 Promise<never> for reject\\nexpectType<Promise<never>>(delay.reject(200, { value: \\"\uD83E\uDD84\\" }));\\nexpectType<Promise<never>>(delay.reject(200, { value: 0 }));\\n\\n// \u6D4B\u8BD5\u51FD\u6570\u7684\u53EF\u8D4B\u503C\u6027 (\u53C2\u6570\u7C7B\u578B\u68C0\u67E5)\\nconst options: Options = { value: \\"test\\" };\\nexpectAssignable<Options>(options);\\n// expectAssignable<Options>({unknownProp: 1}); // \u8FD9\u4F1A\u62A5\u9519\uFF0C\u56E0\u4E3A unknownProp \u4E0D\u5728 Options \u7C7B\u578B\u4E2D\\n\\n// \u6D4B\u8BD5\u9519\u8BEF\u6848\u4F8B (\u7C7B\u578B\u4E0D\u5339\u914D\u6216\u7528\u6CD5\u9519\u8BEF)\\nexpectError(delay(\\"200\\")); // \u53C2\u6570\u7C7B\u578B\u9519\u8BEF\\nexpectError(delay(100, { value: true })); // value \u7C7B\u578B\u9519\u8BEF (\u5047\u8BBE\u5B83\u53EA\u63A5\u53D7 string/number)\\n\\n// \u6D4B\u8BD5\u53EA\u8BFB\u5C5E\u6027\\nconst resultPromise = delay(100, { value: \\"hello\\" });\\nexpectType<Promise<string>>(resultPromise);\\n// resultPromise.value = \'world\'; // \u5982\u679C Promise<string> \u672C\u8EAB\u6CA1\u6709\u7279\u6B8A\u5904\u7406\uFF0C\u8FD9\u884C\u4F1A\u62A5\u9519\\n// \u5BF9\u4E8E\u8FD4\u56DE\u7684\u5BF9\u8C61\uFF0C\u6D4B\u8BD5\u5176\u5C5E\u6027\u662F\u5426\u53EA\u8BFB\\n// const resultObj = await someFuncReturningReadonlyObject();\\n// expectError(resultObj.someProp = \'new value\'); // \u5982\u679C someProp \u662F readonly\\n```\\n\\n**\u7C7B\u578B\u6D4B\u8BD5\u6CE8\u610F\u4E8B\u9879**:\\n\\n- \u7C7B\u578B\u6D4B\u8BD5\u6587\u4EF6\u901A\u5E38\u547D\u540D\u4E3A `*.test-d.ts` (\u4F8B\u5982 `index.test-d.ts`)\uFF0C\u653E\u5728 `test` \u6216 `tests` \u76EE\u5F55\u4E0B\u3002\\n- `tsd` \u652F\u6301\u5728\u6D4B\u8BD5\u6587\u4EF6\u4E2D\u4F7F\u7528\u9876\u5C42 `await` (Top-Level Await)\u3002\\n- **\u91CD\u8981**: \u5728\u6D4B\u8BD5\u8FD4\u56DE Promise \u7684\u51FD\u6570\u65F6\uFF0C**\u4E0D\u8981** \u5728 `expectType` \u4E2D\u4F7F\u7528 `await` \u5173\u952E\u5B57\u3002\u5E94\u76F4\u63A5\u65AD\u8A00\u8FD4\u56DE\u503C\u7684\u7C7B\u578B\u662F `Promise<ExpectedType>`\uFF0C\u5982 `expectType<Promise<string>>(func())`\u3002\\n  - _\u539F\u56E0: \u5982\u679C\u4F60\u5199 `expectType<string>(await func())`\uFF0C\u5373\u4F7F `func` \u610F\u5916\u5730\u8FD4\u56DE\u4E86\u4E00\u4E2A\u975E Promise \u7684\u503C `string`\uFF0C`await` \u4E5F\u4F1A\u6B63\u5E38\u5DE5\u4F5C (\u5B83\u4F1A\u76F4\u63A5\u8FD4\u56DE\u503C)\uFF0C\u5BFC\u81F4\u6D4B\u8BD5\u901A\u8FC7\uFF0C\u4F46\u7C7B\u578B\u5B9A\u4E49 (\u58F0\u660E\u8FD4\u56DE `Promise<string>`) \u5B9E\u9645\u4E0A\u662F\u9519\u8BEF\u7684\u3002\u76F4\u63A5\u6D4B\u8BD5 `Promise<ExpectedType>` \u80FD\u786E\u4FDD\u51FD\u6570\u786E\u5B9E\u8FD4\u56DE\u4E86\u4E00\u4E2A Promise\u3002_\\n- \u5F53\u9700\u8981\u5411\u88AB\u6D4B\u8BD5\u51FD\u6570\u4F20\u9012\u5B57\u9762\u91CF\u7C7B\u578B\u6216\u53EA\u8BFB\u7C7B\u578B\u7684\u503C\u65F6\uFF0C\u53EF\u4EE5\u4F7F\u7528 [**`const` \u65AD\u8A00**](https://www.typescriptlang.org/docs/handbook/release-notes/typescript-3-4.html#const-assertions) (as const)\u3002\u8FD9\u4F1A\u544A\u8BC9 TypeScript \u5C06\u7C7B\u578B\u63A8\u65AD\u4E3A\u6700\u7A84\u7684\u5B57\u9762\u91CF\u7C7B\u578B\u6216\u53EA\u8BFB\u7C7B\u578B\u3002\\n\\n  ```ts\\n  import myLib from \\"./my-lib\\";\\n  import { expectType } from \\"tsd\\";\\n\\n  // \u5047\u8BBE myLib.process \u9700\u8981\u4E00\u4E2A\u5B57\u9762\u91CF\u7C7B\u578B \'literal\' \u6216 \'const\'\\n  const config = { type: \\"literal\\" } as const; // \'as const\' \u4F7F type \u6210\u4E3A \'literal\' \u7C7B\u578B\\n  expectType<void>(myLib.process(config));\\n\\n  const readonlyArray = [\\"a\\", \\"b\\"] as const; // \u63A8\u65AD\u4E3A readonly [\'a\', \'b\']\\n  expectType<readonly string[]>(myLib.handleArray(readonlyArray));\\n  ```\\n\\n- \u9002\u5F53\u65F6\uFF0C\u4F7F\u7528 `expectError()` \u6765\u9A8C\u8BC1\u4E0D\u6B63\u786E\u7684\u7528\u6CD5\u786E\u5B9E\u4F1A\u5BFC\u81F4 TypeScript \u7F16\u8BD1\u9519\u8BEF\u3002\u8FD9\u6709\u52A9\u4E8E\u786E\u4FDD\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u4E0D\u4F1A\u8FC7\u4E8E\u5BBD\u677E\u3002\\n- \u4F7F\u7528 `expectAssignable<Target>(source)` \u6765\u6D4B\u8BD5 `source` \u7C7B\u578B\u7684\u503C\u662F\u5426\u53EF\u4EE5\u8D4B\u503C\u7ED9 `Target` \u7C7B\u578B\u7684\u53D8\u91CF\uFF0C\u8FD9\u5BF9\u4E8E\u68C0\u67E5\u63A5\u53E3\u517C\u5BB9\u6027\u5F88\u6709\u7528\u3002\\n\\n_\u8865\u5145: `tsd` \u6D4B\u8BD5\u662F\u7C7B\u578B\u5B9A\u4E49\u7684\u201C\u5355\u5143\u6D4B\u8BD5\u201D\u3002\u5B83\u4E0D\u8FD0\u884C\u5B9E\u9645\u4EE3\u7801\uFF0C\u800C\u662F\u5229\u7528 TypeScript \u7F16\u8BD1\u5668\u6765\u68C0\u67E5\u7C7B\u578B\u58F0\u660E\u662F\u5426\u7B26\u5408\u9884\u671F\u3002\u8FD9\u5BF9\u4E8E\u7EF4\u62A4\u9AD8\u8D28\u91CF\u3001\u53EF\u9760\u7684\u7C7B\u578B\u5B9A\u4E49\u81F3\u5173\u91CD\u8981\uFF0C\u5C24\u5176\u662F\u5728\u5E93\u4EE3\u7801\u6216\u7C7B\u578B\u5B9A\u4E49\u53D1\u751F\u53D8\u66F4\u65F6\u3002_\\n\\n## \u603B\u7ED3\\n\\n\u4E3A npm \u5305\u63D0\u4F9B\u9AD8\u8D28\u91CF\u7684 TypeScript \u7C7B\u578B\u5B9A\u4E49\u662F\u73B0\u4EE3\u524D\u7AEF\u548C Node.js \u5F00\u53D1\u4E2D\u7684\u4E00\u9879\u91CD\u8981\u5B9E\u8DF5\u3002\u9075\u5FAA\u672C\u6307\u5357\u4E2D\u7684\u7EA6\u5B9A\u548C\u6700\u4F73\u5B9E\u8DF5\uFF0C\u53EF\u4EE5\u5E2E\u52A9\u4F60\u521B\u5EFA\u51FA\u6E05\u6670\u3001\u51C6\u786E\u3001\u6613\u4E8E\u4F7F\u7528\u4E14\u5065\u58EE\u7684\u7C7B\u578B\u5B9A\u4E49\uFF0C\u4ECE\u800C\uFF1A\\n\\n- **\u63D0\u5347\u5F00\u53D1\u8005\u4F53\u9A8C (DX)**\uFF1A\u63D0\u4F9B\u7CBE\u51C6\u7684\u81EA\u52A8\u8865\u5168\u548C\u7C7B\u578B\u63D0\u793A\u3002\\n- **\u589E\u5F3A\u4EE3\u7801\u5065\u58EE\u6027**: \u5728\u7F16\u8BD1\u65F6\u6355\u83B7\u6F5C\u5728\u7684\u7C7B\u578B\u9519\u8BEF\u3002\\n- **\u6539\u5584\u53EF\u7EF4\u62A4\u6027**: \u7C7B\u578B\u5B9A\u4E49\u672C\u8EAB\u5C31\u662F\u4E00\u79CD\u7CBE\u786E\u7684 API \u6587\u6863\u3002\\n- **\u4FC3\u8FDB\u5E93\u7684\u91C7\u7528**: \u826F\u597D\u7684\u7C7B\u578B\u652F\u6301\u662F\u8BB8\u591A\u5F00\u53D1\u8005\u9009\u62E9\u5E93\u7684\u91CD\u8981\u56E0\u7D20\u3002\\n\\n\u6295\u5165\u65F6\u95F4\u7F16\u5199\u548C\u7EF4\u62A4\u9AD8\u8D28\u91CF\u7684 `.d.ts` \u6587\u4EF6\uFF0C\u662F\u5BF9\u4F60\u7684\u5E93\u7528\u6237\u6700\u597D\u7684\u6295\u8D44\u4E4B\u4E00\u3002"},{"id":"/2025/04/05/\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","metadata":{"permalink":"/transblog/2025/04/05/\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","source":"@site/blog-translated/2025/04-05-\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357.md","title":"\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","description":"- \u539F\u6587\u94FE\u63A5\uFF1A https://gist.github.com/sindresorhus/a39789f98801d908bbc7ff3ecc99d99c","date":"2025-04-05T05:28:47.000Z","tags":[{"inline":true,"label":"ESM","permalink":"/transblog/tags/esm"}],"readingTime":18.475,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","date":"2025-04-05T05:28:47.000Z","draft":false,"tags":["ESM"]},"unlisted":false,"prevItem":{"title":"TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","permalink":"/transblog/2025/04/15/TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357"}},"content":"> - \u539F\u6587\u94FE\u63A5\uFF1A https://gist.github.com/sindresorhus/a39789f98801d908bbc7ff3ecc99d99c\\n> - \u673A\u5668\u7FFB\u8BD1\uFF1A Gemini 2.5 Pro Preview\\n> - \u63D0\u793A\u8BCD\uFF1A \u7FFB\u8BD1\u4EE5\u4E0B\u6587\u6863\uFF0C\u5E76\u4E14\u7ED3\u5408\u4F60\u7684\u524D\u7AEF\u5F00\u53D1\u4E13\u4E1A\u77E5\u8BC6\u8865\u5145\u76F8\u5173\u7684\u77E5\u8BC6\u70B9\u8BF4\u660E\uFF0C\u5BF9\u6587\u7AE0\u5185\u5BB9\u8FDB\u884C\u7ED3\u6784\u5316\uFF0C\u4EE5 Markdown \u683C\u5F0F\u8FD4\u56DE\uFF0C\u6587\u5B57\u98CE\u683C\u662F\u6280\u672F\u535A\u5BA2\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n## \u6838\u5FC3\u95EE\u9898\uFF1A\u65E0\u6CD5\u518D\u4F7F\u7528 `require()`\\n\\n**\u5173\u952E\u70B9**\uFF1A\u4E00\u4E2A Pure ESM \u5305\u4E0D\u80FD\u518D\u901A\u8FC7 CommonJS \u7684 `require()` \u51FD\u6570\u6765\u540C\u6B65\u5BFC\u5165\u3002\\n\\n```javascript\\n// \u274C \u8FD9\u79CD\u65B9\u5F0F\u5728 CommonJS \u9879\u76EE\u4E2D\u4F1A\u62A5\u9519\\n// const foo = require(\'pure-esm-package\');\\n\\n// \u2705 \u9700\u8981\u6539\u7528 ESM \u7684 import \u8BED\u6CD5\\n// import foo from \'pure-esm-package\';\\n```\\n\\n\u8FD9\u79CD\u8F6C\u53D8\u662F JavaScript \u751F\u6001\u7CFB\u7EDF\u9010\u6B65\u62E5\u62B1\u5B98\u65B9\u6807\u51C6\u6A21\u5757\u7CFB\u7EDF\u7684\u4E00\u90E8\u5206\u3002\u867D\u7136\u5E26\u6765\u4E86\u9635\u75DB\uFF0C\u4F46\u957F\u8FDC\u6765\u770B\uFF0C\u5B83\u7EDF\u4E00\u4E86\u524D\u540E\u7AEF\u7684\u6A21\u5757\u89C4\u8303\uFF0C\u5E26\u6765\u4E86\u8BF8\u591A\u597D\u5904\u3002\\n\\n## \u5982\u4F55\u5E94\u5BF9 Pure ESM \u5305\uFF1F\\n\\n\u9762\u5BF9\u8FD9\u79CD\u60C5\u51B5\uFF0C\u4F60\u6709\u4EE5\u4E0B\u51E0\u79CD\u9009\u62E9\uFF1A\\n\\n1.  **\u8FC1\u79FB\u4F60\u7684\u9879\u76EE\u5230 ESM (\u5F3A\u70C8\u63A8\u8350)**\uFF1A\\n\\n    - **\u65B9\u6CD5**\uFF1A\u5728\u4F60\u7684\u4EE3\u7801\u4E2D\u4F7F\u7528 `import foo from \'pure-esm-package\'` \u66FF\u4EE3 `const foo = require(\'pure-esm-package\')`\u3002\\n    - **\u914D\u5957\u63AA\u65BD**\uFF1A\u9700\u8981\u5728 `package.json` \u4E2D\u6DFB\u52A0 `\\"type\\": \\"module\\"` \u58F0\u660E\uFF0C\u5E76\u53EF\u80FD\u9700\u8981\u8C03\u6574\u6784\u5EFA\u914D\u7F6E\u3001\u6587\u4EF6\u6269\u5C55\u540D\u7B49\u3002\u4E0B\u6587\u4F1A\u8BE6\u7EC6\u4ECB\u7ECD\u3002\\n    - **\u524D\u7AEF\u89C6\u89D2**\uFF1A\u73B0\u4EE3\u524D\u7AEF\u6846\u67B6\uFF08\u5982 Vue 3, React with Vite, SvelteKit, Next.js 12+\uFF09\u539F\u751F\u6216\u66F4\u597D\u5730\u652F\u6301 ESM\u3002\u8FC1\u79FB\u5230 ESM \u53EF\u4EE5\u66F4\u597D\u5730\u5229\u7528 Tree Shaking\uFF08\u6447\u6811\u4F18\u5316\uFF09\u51CF\u5C11\u6700\u7EC8\u6253\u5305\u4F53\u79EF\uFF0C\u5E76\u4E0E\u6D4F\u89C8\u5668\u539F\u751F\u6A21\u5757\u52A0\u8F7D\u673A\u5236\u4FDD\u6301\u4E00\u81F4\u3002\\n\\n2.  **\u5728 CommonJS \u4E2D\u4F7F\u7528\u52A8\u6001 `import()` (\u5F02\u6B65\u4E0A\u4E0B\u6587)**\uFF1A\\n\\n    - **\u65B9\u6CD5**\uFF1A\u5982\u679C\u4F60\u7684\u4EE3\u7801\u5141\u8BB8\u5F02\u6B65\u64CD\u4F5C\uFF0C\u53EF\u4EE5\u4F7F\u7528 `await import(\'pure-esm-package\')` \u6765\u52A0\u8F7D ESM \u5305\u3002\\n    - **\u793A\u4F8B**:\\n      ```javascript\\n      // \u5728 async \u51FD\u6570\u6216\u9876\u5C42 await (Node.js >= 14.8) \u4E2D\\n      async function loadMyModule() {\\n        const { default: foo } = await import(\\"pure-esm-package\\");\\n        // \u6CE8\u610F\uFF1AESM \u9ED8\u8BA4\u5BFC\u51FA\u7684\u6A21\u5757\u9700\u8981\u901A\u8FC7 .default \u8BBF\u95EE\\n        // \u5982\u679C\u662F\u547D\u540D\u5BFC\u51FA\uFF0C\u5219\uFF1A const { namedExport } = await import(\'pure-esm-package\');\\n        foo.doSomething();\\n      }\\n      ```\\n    - **\u9650\u5236**\uFF1A\u8FD9\u53EA\u80FD\u5728\u5F02\u6B65\u51FD\u6570\u6216\u652F\u6301\u9876\u5C42 `await` \u7684\u73AF\u5883\u4E2D\u4F7F\u7528\u3002\u65E0\u6CD5\u7528\u4E8E\u9700\u8981\u540C\u6B65\u8FD4\u56DE\u6A21\u5757\u7684\u573A\u666F\u3002\\n    - **\u524D\u7AEF\u89C6\u89D2**\uFF1A\u52A8\u6001 `import()` \u5728\u524D\u7AEF\u5E38\u7528\u4E8E\u4EE3\u7801\u5206\u5272\uFF08Code Splitting\uFF09\uFF0C\u6309\u9700\u52A0\u8F7D\u8DEF\u7531\u6216\u7EC4\u4EF6\uFF0C\u4EE5\u4F18\u5316\u9996\u5C4F\u52A0\u8F7D\u6027\u80FD\u3002\u8FD9\u91CC\u7684\u7528\u6CD5\u7C7B\u4F3C\uFF0C\u4F46\u76EE\u7684\u662F\u89E3\u51B3 CJS/ESM \u4E92\u64CD\u4F5C\u6027\u95EE\u9898\u3002\\n\\n3.  **\u9501\u5B9A\u65E7\u7248\u672C**\uFF1A\\n\\n    - **\u65B9\u6CD5**\uFF1A\u6682\u65F6\u505C\u7559\u5728\u8BE5 Pure ESM \u5305\u7684\u6700\u540E\u4E00\u4E2A CommonJS \u517C\u5BB9\u7248\u672C\u3002\\n    - **\u98CE\u9669**\uFF1A\u4F60\u5C06\u65E0\u6CD5\u83B7\u5F97\u8BE5\u5305\u540E\u7EED\u7684\u65B0\u529F\u80FD\u3001\u6027\u80FD\u4F18\u5316\u548C\u5B89\u5168\u4FEE\u590D\u3002\u8FD9\u901A\u5E38\u53EA\u662F\u4E00\u4E2A\u77ED\u671F\u7F13\u5175\u4E4B\u8BA1\u3002\\n\\n4.  **\u5C1D\u8BD5 Node.js 22+ \u7684 `require()` ESM \u652F\u6301 (\u4E0D\u63A8\u8350)**\uFF1A\\n    - **\u80CC\u666F**\uFF1ANode.js 22 \u5F00\u59CB\u5B9E\u9A8C\u6027\u5730\u652F\u6301\u901A\u8FC7 `require()` \u52A0\u8F7D _\u540C\u6B65_ ESM \u6A21\u5757\u56FE\u3002\\n    - **\u5F3A\u70C8\u5EFA\u8BAE**\uFF1A**\u5B98\u65B9\u548C\u793E\u533A\u666E\u904D\u4E0D\u63A8\u8350\u4F9D\u8D56\u6B64\u7279\u6027**\u3002\u5B83\u53EF\u80FD\u5B58\u5728\u6027\u80FD\u95EE\u9898\u3001\u517C\u5BB9\u6027\u9677\u9631\uFF0C\u4E14\u8FDD\u80CC\u4E86 ESM \u7684\u8BBE\u8BA1\u54F2\u5B66\u3002**\u8FC1\u79FB\u5230 ESM \u624D\u662F\u6B63\u9014\u3002**\\n\\n**\u6700\u4F4E\u73AF\u5883\u8981\u6C42**\uFF1A\u8BF7\u786E\u4FDD\u4F60\u7684 Node.js \u7248\u672C\u81F3\u5C11\u4E3A v16\uFF0C**\u5F3A\u70C8\u63A8\u8350\u4F7F\u7528 Node.js 18 \u6216\u66F4\u9AD8\u7248\u672C**\uFF0C\u56E0\u4E3A\u8BB8\u591A\u73B0\u4EE3\u5DE5\u5177\u548C\u5E93\u90FD\u5DF2\u5C06\u6B64\u4F5C\u4E3A\u6700\u4F4E\u8981\u6C42\uFF0C\u5E76\u4E14\u5BF9 ESM \u7684\u652F\u6301\u66F4\u4E3A\u5B8C\u5584\u3002\\n\\n**\u6838\u5FC3\u7406\u5FF5**\uFF1AESM \u53EF\u4EE5\u5BFC\u5165 CommonJS \u5305\uFF08\u901A\u5E38\u6CA1\u6709\u95EE\u9898\uFF09\uFF0C\u4F46 CommonJS \u5305\u65E0\u6CD5\u540C\u6B65 `require()` ESM \u5305\u3002\u8FD9\u662F\u5355\u5411\u7684\u517C\u5BB9\u6027\u3002\\n\\n**\u8BF7\u6CE8\u610F**\uFF1A\u4F5C\u8005\u660E\u786E\u8868\u793A\uFF0C\u5176\u4ED3\u5E93**\u4E0D\u662F**\u89E3\u7B54\u901A\u7528 ESM\u3001TypeScript\u3001Webpack\u3001Jest\u3001ts-node\u3001Create React App (CRA) \u7B49\u5DE5\u5177\u652F\u6301\u95EE\u9898\u7684\u573A\u6240\u3002\u8BF7\u67E5\u9605\u76F8\u5E94\u5DE5\u5177\u7684\u5B98\u65B9\u6587\u6863\u6216\u793E\u533A\u3002\\n\\n---\\n\\n## FAQ\uFF1A\u8FC1\u79FB\u4E0E\u5B9E\u8DF5\u8BE6\u89E3\\n\\n### Q1: \u5982\u4F55\u5C06\u6211\u7684 CommonJS \u9879\u76EE\u8FC1\u79FB\u5230 ESM\uFF1F\\n\\n\u4EE5\u4E0B\u662F\u5173\u952E\u6B65\u9AA4\uFF1A\\n\\n1.  **`package.json` \u8BBE\u7F6E**\uFF1A\\n\\n    - \u6DFB\u52A0 `\\"type\\": \\"module\\"`\u3002\u8FD9\u544A\u8BC9 Node.js (\u548C\u8BB8\u591A\u6784\u5EFA\u5DE5\u5177) \u9ED8\u8BA4\u5C06 `.js` \u6587\u4EF6\u89C6\u4E3A ESM\u3002\\n    - \u5C06 `\\"main\\": \\"index.js\\"` \u66FF\u6362\u4E3A `\\"exports\\": \\"./index.js\\"`\u3002`\\"exports\\"` \u5B57\u6BB5\u63D0\u4F9B\u4E86\u66F4\u7CBE\u7EC6\u7684\u5305\u5165\u53E3\u70B9\u63A7\u5236\uFF0C\u662F\u73B0\u4EE3 Node.js \u5305\u7684\u6807\u51C6\u3002\\n    - \u66F4\u65B0 `\\"engines\\"` \u5B57\u6BB5\uFF0C\u5EFA\u8BAE\u81F3\u5C11 `\\"node\\": \\">=18\\"`\u3002\\n\\n2.  **\u4EE3\u7801\u8C03\u6574**\uFF1A\\n\\n    - \u79FB\u9664\u6240\u6709\u6587\u4EF6\u9876\u90E8\u7684 `\'use strict\';` (ESM \u9ED8\u8BA4\u5C31\u662F\u4E25\u683C\u6A21\u5F0F)\u3002\\n    - \u5C06\u6240\u6709 `require()` \u548C `module.exports` / `exports.*` \u66FF\u6362\u4E3A `import` \u548C `export` \u8BED\u6CD5\u3002\\n    - **\u4F7F\u7528\u5B8C\u6574\u7684\u76F8\u5BF9\u6587\u4EF6\u8DEF\u5F84**\uFF1A\u5BFC\u5165\u672C\u5730\u6587\u4EF6\u65F6\u5FC5\u987B\u5305\u542B\u6587\u4EF6\u6269\u5C55\u540D\uFF08\u901A\u5E38\u662F `.js`\uFF0C\u5373\u4F7F\u6E90\u6587\u4EF6\u662F `.ts` \u7F16\u8BD1\u540E\u4E5F\u5E94\u5BFC\u5165 `.js`\uFF09\u3002\u4F8B\u5982\uFF1A`import x from \'./utils\';` \u9700\u6539\u4E3A `import x from \'./utils.js\';`\u3002\\n    - \u5BFC\u5165 Node.js \u5185\u7F6E\u6A21\u5757\u65F6\uFF0C\u4F7F\u7528 `node:` \u534F\u8BAE\u524D\u7F00\uFF0C\u4F8B\u5982\uFF1A`import fs from \'node:fs\';`\u3002\u8FD9\u80FD\u660E\u786E\u533A\u5206\u5185\u7F6E\u6A21\u5757\u548C\u7B2C\u4E09\u65B9\u6A21\u5757\uFF0C\u5E76\u6709\u52A9\u4E8E\u67D0\u4E9B\u573A\u666F\u4E0B\u7684\u89E3\u6790\u3002\\n\\n3.  **TypeScript \u7C7B\u578B\u5B9A\u4E49 (\u5982\u679C\u9002\u7528)**\uFF1A\\n    - \u5982\u679C\u4F60\u7684\u5305\u5305\u542B\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6 (\u5982 `index.d.ts`)\uFF0C\u786E\u4FDD\u5176\u4E2D\u7684\u5BFC\u5165/\u5BFC\u51FA\u8BED\u6CD5\u4E5F\u66F4\u65B0\u4E3A ESM \u683C\u5F0F\u3002\\n\\n**\u6269\u5C55\u9605\u8BFB**\uFF1A\u5982\u679C\u4F60\u5BF9\u5982\u4F55\u4E3A JavaScript \u5305\u6DFB\u52A0\u7C7B\u578B\u5B9A\u4E49\u611F\u5174\u8DA3\uFF0C\u53EF\u4EE5\u53C2\u8003\u4F5C\u8005\u7684 [TypeScript Definition Style Guide](https://github.com/sindresorhus/typescript-definition-style-guide)\u3002\\n\\n### Q2: \u5982\u4F55\u5728 TypeScript \u9879\u76EE\u4E2D\u4F7F\u7528 (\u6216\u8F93\u51FA) ESM\uFF1F\\n\\n\u662F\u7684\uFF0C\u5B8C\u5168\u53EF\u4EE5\uFF01\u4F60\u9700\u8981\u914D\u7F6E TypeScript \u9879\u76EE\u4EE5\u8F93\u51FA ESM \u683C\u5F0F\u7684\u4EE3\u7801\u3002\\n\\n**\u5173\u952E\u6B65\u9AA4**\uFF1A\\n\\n1.  **TypeScript \u7248\u672C**\uFF1A\u786E\u4FDD\u4F7F\u7528 TypeScript 4.7 \u6216\u66F4\u9AD8\u7248\u672C\u3002\\n2.  **`package.json` \u914D\u7F6E**\uFF1A\\n    - \u6DFB\u52A0 `\\"type\\": \\"module\\"`\u3002\\n    - \u5C06 `\\"main\\"` \u66FF\u6362\u4E3A `\\"exports\\"` (\u540C\u4E0A)\u3002\\n    - \u66F4\u65B0 `\\"engines\\"` \u81F3 Node.js 18+ (\u540C\u4E0A)\u3002\\n3.  **`tsconfig.json` \u914D\u7F6E**\uFF1A\\n    - \u8BBE\u7F6E `\\"module\\": \\"node16\\"` \u6216 `\\"module\\": \\"nodenext\\"`\u3002**\u975E\u5E38\u91CD\u8981**\uFF0C\u8FD9\u6307\u793A TypeScript \u751F\u6210\u4E0E Node.js ESM \u517C\u5BB9\u7684 JavaScript \u4EE3\u7801\u3002\\n    - \u8BBE\u7F6E `\\"moduleResolution\\": \\"node16\\"` \u6216 `\\"moduleResolution\\": \\"nodenext\\"`\u3002**\u540C\u6837\u91CD\u8981**\uFF0C\u8FD9\u544A\u8BC9 TypeScript \u7F16\u8BD1\u5668\u5982\u4F55\u67E5\u627E\u6A21\u5757\uFF0C\u4F7F\u5176\u884C\u4E3A\u4E0E Node.js \u7684 ESM \u89E3\u6790\u89C4\u5219\u4E00\u81F4\u3002**\u7EDD\u5BF9\u4E0D\u80FD\u8BBE\u4E3A `\\"node\\"`\uFF01**\\n    - _\u793A\u4F8B\u914D\u7F6E\u53C2\u8003\uFF1A[sindresorhus/tsconfig](https://github.com/sindresorhus/tsconfig/blob/main/tsconfig.json)_\\n4.  **\u4EE3\u7801\u8C03\u6574**\uFF1A\\n    - **\u5FC5\u987B\u4F7F\u7528 `.js` \u6269\u5C55\u540D\u8FDB\u884C\u76F8\u5BF9\u5BFC\u5165**\uFF0C\u5373\u4F7F\u4F60\u5B9E\u9645\u5BFC\u5165\u7684\u662F `.ts` \u6587\u4EF6\u3002TypeScript \u4F1A\u5728\u7F16\u8BD1\u65F6\u6B63\u786E\u5904\u7406\u5B83\u4EEC\u3002`import util from \'./util\';` -> `import util from \'./util.js\';`\\n    - \u79FB\u9664 `namespace` \u7528\u6CD5\uFF0C\u6539\u7528 `export`\u3002\\n    - \u4F7F\u7528 `node:` \u534F\u8BAE\u5BFC\u5165 Node.js \u5185\u7F6E\u6A21\u5757\u3002\\n\\n**\u5173\u4E8E `ts-node`**\uFF1A\u5982\u679C\u4F7F\u7528 `ts-node` \u76F4\u63A5\u8FD0\u884C TS \u4EE3\u7801\uFF0C\u9700\u8981\u9075\u5FAA [ts-node ESM \u6307\u5357](https://github.com/TypeStrong/ts-node/issues/1007)\u3002\u53C2\u8003\u914D\u7F6E\uFF1A[Example config](https://github.com/sindresorhus/got/blob/5f278d74125608b7abe75941cb6a71e21e0fb892/tsconfig.json#L17-L21)\u3002(\u63A8\u8350\u4F7F\u7528 `tsx` \u4F5C\u4E3A\u66FF\u4EE3\u54C1)\\n\\n### Q3: Electron \u4E2D\u5982\u4F55\u4F7F\u7528 ESM\uFF1F\\n\\nElectron \u4ECE\u7248\u672C 28 \u5F00\u59CB\u652F\u6301 ESM\u3002\u8BF7\u53C2\u8003 [Electron ESM \u5B98\u65B9\u6587\u6863](https://github.com/electron/electron/blob/main/docs/tutorial/esm.md)\u3002\\n\\n### Q4: Webpack \u6784\u5EFA\u9047\u5230 ESM \u95EE\u9898\u600E\u4E48\u529E\uFF1F\\n\\n\u95EE\u9898\u5F88\u53EF\u80FD\u51FA\u5728 Webpack \u672C\u8EAB\u6216\u4F60\u7684 Webpack \u914D\u7F6E\u4E0A\u3002\\n\\n1.  \u786E\u4FDD\u4F60\u4F7F\u7528\u7684\u662F\u6700\u65B0\u7248\u672C\u7684 Webpack\u3002\\n2.  \u68C0\u67E5\u4F60\u7684 `webpack.config.js` \u662F\u5426\u6B63\u786E\u5904\u7406\u4E86 `.js` / `.mjs` \u6587\u4EF6\u4EE5\u53CA `package.json` \u4E2D\u7684 `\\"type\\": \\"module\\"`\u3002\u53EF\u80FD\u9700\u8981\u8C03\u6574 `resolve`\u3001`module.rules` \u7B49\u914D\u7F6E\u3002\\n3.  **\u4E0D\u8981** \u5728\u539F\u4F5C\u8005\u7684\u4ED3\u5E93\u63D0\u95EE\u3002\u5C1D\u8BD5\u5728 Stack Overflow \u63D0\u95EE\u6216\u5728 [Webpack \u7684 GitHub \u4ED3\u5E93](https://github.com/webpack/webpack) \u63D0\u4EA4 issue\u3002\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1AWebpack 5 \u5BF9 ESM \u6709\u4E86\u66F4\u597D\u7684\u539F\u751F\u652F\u6301\uFF0C\u4F46\u4E0E CJS \u6DF7\u7528\u3001\u4F9D\u8D56\u9879\u7684\u6A21\u5757\u683C\u5F0F\u3001\u4EE5\u53CA loader/plugin \u7684\u517C\u5BB9\u6027\u4ECD\u53EF\u80FD\u5F15\u53D1\u95EE\u9898\u3002\u786E\u4FDD `experiments.outputModule` (\u5982\u679C\u9700\u8981\u8F93\u51FA ESM bundle) \u6216 `module.rules` \u4E2D\u5BF9 `.mjs` \u548C `.js` (\u5728 `\\"type\\": \\"module\\"` \u9879\u76EE\u4E2D) \u7684\u5904\u7406\u662F\u6B63\u786E\u7684\u3002Vite \u7B49\u57FA\u4E8E\u539F\u751F ESM \u7684\u6784\u5EFA\u5DE5\u5177\u901A\u5E38\u80FD\u66F4\u987A\u7545\u5730\u5904\u7406 ESM \u4F9D\u8D56\u3002\\n\\n### Q5: Next.js \u6784\u5EFA\u9047\u5230 ESM \u95EE\u9898\u600E\u4E48\u529E\uFF1F\\n\\n\u5347\u7EA7\u5230 **Next.js 12 \u6216\u66F4\u9AD8\u7248\u672C**\u3002Next.js 12 \u5F15\u5165\u4E86\u5BF9 ESM \u7684\u5168\u9762\u652F\u6301\uFF0C\u5305\u62EC npm \u5305\u548C URL Imports\u3002\\n\\n### Q6: Jest \u6D4B\u8BD5\u9047\u5230 ESM \u95EE\u9898\u600E\u4E48\u529E\uFF1F\\n\\nJest \u5BF9 ESM \u7684\u652F\u6301\u4ECD\u5728\u53D1\u5C55\u4E2D\u3002\\n\\n1.  \u9605\u8BFB [Jest \u5B98\u65B9 ESM \u6587\u6863](https://jestjs.io/docs/ecmascript-modules)\u3002\\n2.  \u4F60\u53EF\u80FD\u9700\u8981\uFF1A\\n    - \u5728 Node.js \u8FD0\u884C\u65F6\u6DFB\u52A0 `--experimental-vm-modules` \u6807\u5FD7 (\u901A\u8FC7 `NODE_OPTIONS` \u73AF\u5883\u53D8\u91CF)\u3002\\n    - \u4F7F\u7528 `jest-environment-node` \u6216\u81EA\u5B9A\u4E49\u73AF\u5883\u3002\\n    - \u914D\u7F6E `transform` \u9009\u9879\u6765\u5904\u7406 ESM \u8BED\u6CD5\uFF08\u5982\u679C\u9700\u8981\u8F6C\u8BD1\uFF09\u6216\u8BBE\u7F6E\u4E3A\u7A7A\u5BF9\u8C61 `{}` \u4EE5\u7981\u7528 CommonJS \u8F6C\u6362\u3002\\n    - \u786E\u4FDD\u4F60\u7684 `package.json` \u8BBE\u7F6E\u4E86 `\\"type\\": \\"module\\"`\u3002\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1AVitest \u662F\u4E00\u4E2A\u57FA\u4E8E Vite \u7684\u73B0\u4EE3\u6D4B\u8BD5\u6846\u67B6\uFF0C\u5B83\u539F\u751F\u652F\u6301 ESM\uFF0C\u5E76\u4E14\u914D\u7F6E\u901A\u5E38\u6BD4 Jest \u66F4\u7B80\u5355\uFF0C\u53EF\u4EE5\u4F5C\u4E3A Jest \u7684\u66FF\u4EE3\u65B9\u6848\u3002\\n\\n### Q7: TypeScript + ESM \u9047\u5230\u7684\u5176\u4ED6\u95EE\u9898\uFF1F\\n\\n\u518D\u6B21\u786E\u8BA4\uFF1A\\n\\n1.  `package.json` \u4E2D\u6709 `\\"type\\": \\"module\\"`\u3002\\n2.  `tsconfig.json` \u4E2D\u8BBE\u7F6E\u4E86 `\\"module\\": \\"node16\\"` (\u6216 `nodenext`)\u3002\\n3.  \u6240\u6709**\u672C\u5730\u6587\u4EF6**\u7684\u5BFC\u5165\u8BED\u53E5\u90FD\u4F7F\u7528\u4E86 `.js` \u6269\u5C55\u540D\u3002\\n\\n### Q8: `ts-node` + ESM \u9047\u5230\u7684\u95EE\u9898\uFF1F\\n\\n**\u63A8\u8350\u66FF\u4EE3\u54C1**\uFF1A\u8003\u8651\u4F7F\u7528 [`tsx`](https://github.com/privatenumber/tsx)\uFF0C\u5B83\u63D0\u4F9B\u4E86\u66F4\u597D\u7684 ESM \u652F\u6301\u548C\u6027\u80FD\u3002\\n\\n\u5982\u679C\u4ECD\u8981\u4F7F\u7528 `ts-node`\uFF0C\u8BF7\u786E\u4FDD\u662F\u6700\u65B0\u7248\u672C\uFF0C\u5E76\u9075\u5FAA [\u8FD9\u4E2A\u6307\u5357](https://github.com/TypeStrong/ts-node/issues/1007)\u3002[\u793A\u4F8B\u914D\u7F6E](https://github.com/sindresorhus/got/blob/5f278d74125608b7abe75941cb6a71e21e0fb892/tsconfig.json#L17-L21)\u3002\\n\\n### Q9: Create React App (CRA) \u9047\u5230 ESM \u95EE\u9898\u600E\u4E48\u529E\uFF1F\\n\\nCRA \u5BF9 Pure ESM \u5305\u7684\u652F\u6301\u8FD8\u4E0D\u5B8C\u5584\u3002\u5DF2\u77E5\u95EE\u9898\u5982 [#10933](https://github.com/facebook/create-react-app/issues/10933)\u3002\\n\\n- **\u5EFA\u8BAE**\uFF1A\u5411 CRA \u4ED3\u5E93\u62A5\u544A\u4F60\u9047\u5230\u7684\u5177\u4F53\u95EE\u9898\u3002\\n- **\u524D\u7AEF\u8865\u5145**\uFF1ACRA \u7684\u5E95\u5C42\u6784\u5EFA\u5DE5\u5177 (Webpack) \u548C\u914D\u7F6E\u53EF\u80FD\u6CA1\u6709\u5B8C\u5168\u8DDF\u4E0A ESM \u7684\u6B65\u4F10\u3002\u5BF9\u4E8E\u65B0\u9879\u76EE\u6216\u9700\u8981\u66F4\u597D ESM \u652F\u6301\u7684\u9879\u76EE\uFF0C\u53EF\u4EE5\u8003\u8651\u4F7F\u7528 Vite + React \u6A21\u677F\uFF0CVite \u5BF9 ESM \u7684\u539F\u751F\u652F\u6301\u4F7F\u5176\u5904\u7406\u8FD9\u7C7B\u4F9D\u8D56\u66F4\u52A0\u987A\u7545\u3002\\n\\n### Q10: \u5982\u4F55\u5728 ESM \u9879\u76EE\u4E2D\u4F7F\u7528 TypeScript \u548C AVA \u8FDB\u884C\u6D4B\u8BD5\uFF1F\\n\\n\u9075\u5FAA [AVA \u5B98\u65B9 TypeScript \u6307\u5357 (\u9488\u5BF9 type: module \u5305)](https://github.com/avajs/ava/blob/main/docs/recipes/typescript.md#for-packages-with-type-module)\u3002\\n\\n### Q11: \u5982\u4F55\u786E\u4FDD\u4E0D\u610F\u5916\u4F7F\u7528 CommonJS \u7279\u6709\u7684\u5199\u6CD5\uFF1F\\n\\n\u4F7F\u7528 ESLint \u89C4\u5219\u6765\u5F3A\u5236\u6267\u884C ESM \u6700\u4F73\u5B9E\u8DF5\uFF1A\\n\\n- [`eslint-plugin-unicorn/prefer-module`](https://github.com/sindresorhus/eslint-plugin-unicorn/blob/main/docs/rules/prefer-module.md): \u5F3A\u5236\u4F7F\u7528 ESM \u98CE\u683C\uFF08`import`/`export`\uFF0C`.js` \u6269\u5C55\u540D\u7B49\uFF09\u3002\\n- [`eslint-plugin-unicorn/prefer-node-protocol`](https://github.com/sindresorhus/eslint-plugin-unicorn/blob/main/docs/rules/prefer-node-protocol.md): \u5F3A\u5236\u4F7F\u7528 `node:` \u534F\u8BAE\u5BFC\u5165\u5185\u7F6E\u6A21\u5757\u3002\\n\\n### Q12: ESM \u4E2D\u6CA1\u6709 `__dirname` \u548C `__filename`\uFF0C\u600E\u4E48\u529E\uFF1F\\n\\n\u4F7F\u7528 `import.meta.url` \u6765\u83B7\u53D6\u5F53\u524D\u6A21\u5757\u7684 URL\u3002\\n\\n- **Node.js 20.11+ / 21.2+**:\\n\\n  - \u53EF\u4EE5\u76F4\u63A5\u4F7F\u7528 `import.meta.dirname` \u548C `import.meta.filename`\u3002\\n\\n- **\u65E7\u7248 Node.js**:\\n\\n  ```javascript\\n  import { fileURLToPath } from \\"node:url\\";\\n  import path from \\"node:path\\";\\n\\n  // \u83B7\u53D6\u5F53\u524D\u6587\u4EF6\u7684\u7EDD\u5BF9\u8DEF\u5F84\\n  const __filename = fileURLToPath(import.meta.url);\\n  // \u83B7\u53D6\u5F53\u524D\u6587\u4EF6\u6240\u5728\u76EE\u5F55\u7684\u7EDD\u5BF9\u8DEF\u5F84\\n  const __dirname = path.dirname(__filename); // \u6216\u8005 path.dirname(fileURLToPath(import.meta.url))\\n  ```\\n\\n- **\u66F4\u5E38\u7528\u7684\u6A21\u5F0F (\u6784\u9020\u76F8\u5BF9\u4E8E\u5F53\u524D\u6A21\u5757\u7684\u8DEF\u5F84)**:\\n\\n  ```javascript\\n  import { fileURLToPath } from \\"node:url\\";\\n\\n  // \u83B7\u53D6\u540C\u76EE\u5F55\u4E0B foo.js \u7684\u6587\u4EF6\u7CFB\u7EDF\u8DEF\u5F84\\n  const fooPath = fileURLToPath(new URL(\\"foo.js\\", import.meta.url));\\n  ```\\n\\n- **\u8BB8\u591A Node.js API \u76F4\u63A5\u63A5\u53D7 URL \u5BF9\u8C61**:\\n  ```javascript\\n  // \u76F4\u63A5\u521B\u5EFA URL \u5BF9\u8C61\uFF0C\u53EF\u80FD\u53EF\u4EE5\u76F4\u63A5\u4F20\u9012\u7ED9\u67D0\u4E9B API (\u5982 fs.readFile)\\n  const fooUrl = new URL(\\"foo.js\\", import.meta.url);\\n  // await fs.readFile(fooUrl); // \u793A\u4F8B\\n  ```\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1A\u5728\u6D4F\u89C8\u5668\u73AF\u5883\u4E2D\uFF0C`import.meta.url` \u540C\u6837\u53EF\u7528\uFF0C\u5B83\u8FD4\u56DE\u7684\u662F\u6A21\u5757\u7684 URL\u3002\u4F46\u5728\u524D\u7AEF\u6784\u5EFA\u6253\u5305\u540E\uFF0C\u8FD9\u4E2A\u503C\u53EF\u80FD\u6307\u5411 `blob:` URL \u6216\u6253\u5305\u540E\u7684\u6587\u4EF6\u8DEF\u5F84\uFF0C\u5176\u884C\u4E3A\u53EF\u80FD\u4E0E Node.js \u73AF\u5883\u4E0D\u5B8C\u5168\u4E00\u81F4\u3002\u901A\u5E38\u5728\u524D\u7AEF\u4EE3\u7801\u4E2D\u76F4\u63A5\u64CD\u4F5C\u6587\u4EF6\u7CFB\u7EDF\u7684\u573A\u666F\u8F83\u5C11\uFF0C\u66F4\u591A\u662F\u5904\u7406\u76F8\u5BF9\u8D44\u6E90\u7684 URL\u3002\\n\\n### Q13: \u6D4B\u8BD5\u65F6\u5982\u4F55\u5BFC\u5165\u6A21\u5757\u5E76\u7ED5\u8FC7\u7F13\u5B58\uFF1F\\n\\n\u5728 ESM \u4E2D\uFF0C\u6CA1\u6709\u50CF CommonJS `delete require.cache[modulePath]` \u90A3\u6837\u6807\u51C6\u7684\u3001\u7B80\u5355\u7684\u65B9\u6CD5\u6765\u6E05\u9664\u7F13\u5B58\u3002\\n\\n- **\u4E34\u65F6\u65B9\u6848 (\u4EC5\u9650\u6D4B\u8BD5\uFF0C\u6709\u5185\u5B58\u6CC4\u6F0F\u98CE\u9669\uFF01)**: \u901A\u8FC7\u7ED9\u5BFC\u5165\u8DEF\u5F84\u6DFB\u52A0\u52A8\u6001\u67E5\u8BE2\u53C2\u6570\u6765\u5F3A\u5236\u91CD\u65B0\u52A0\u8F7D\u3002\\n\\n  ```javascript\\n  const importFresh = async (modulePath) => {\\n    // \u6DFB\u52A0\u65F6\u95F4\u6233\u4F5C\u4E3A\u67E5\u8BE2\u53C2\u6570\uFF0C\u6B3A\u9A97\u6A21\u5757\u52A0\u8F7D\u5668\u8BA4\u4E3A\u662F\u4E0D\u540C\u7684\u6A21\u5757\\n    return import(`${modulePath}?t=${Date.now()}`);\\n  };\\n\\n  // \u4F7F\u7528\u793A\u4F8B\\n  const chalk = (await importFresh(\\"chalk\\")).default;\\n  ```\\n\\n  **\u8B66\u544A**:\\n\\n  1.  \u8FD9\u79CD\u65B9\u6CD5\u4F1A**\u5BFC\u81F4\u5185\u5B58\u6CC4\u6F0F**\uFF0C\u56E0\u4E3A\u65E7\u6A21\u5757\u5B9E\u4F8B\u4E0D\u4F1A\u88AB\u5783\u573E\u56DE\u6536\u3002**\u7EDD\u5BF9\u4E0D\u8981\u5728\u751F\u4EA7\u73AF\u5883\u4E2D\u4F7F\u7528**\u3002\\n  2.  \u5B83\u53EA\u4F1A\u91CD\u65B0\u52A0\u8F7D\u4F60\u76F4\u63A5\u5BFC\u5165\u7684\u90A3\u4E2A\u6A21\u5757\uFF0C**\u4E0D\u4F1A**\u91CD\u65B0\u52A0\u8F7D\u5176\u4F9D\u8D56\u9879\u3002\\n\\n- **\u672A\u6765**\uFF1ANode.js \u7684 [ESM Loader Hooks](https://github.com/nodejs/modules/issues/307) \u6210\u719F\u540E\u53EF\u80FD\u4F1A\u63D0\u4F9B\u66F4\u597D\u7684\u89E3\u51B3\u65B9\u6848\u3002\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1A\u5728\u6D4F\u89C8\u5668\u7AEF\uFF0C\u6A21\u5757\u7F13\u5B58\u7531\u6D4F\u89C8\u5668\u7BA1\u7406\u3002\u6D4B\u8BD5\u6846\u67B6\uFF08\u5982 Vitest\uFF09\u901A\u5E38\u6709\u81EA\u5DF1\u7684\u6A21\u5757\u6A21\u62DF\uFF08mocking\uFF09\u548C\u9694\u79BB\u673A\u5236\uFF0C\u4E0D\u4F9D\u8D56\u8FD9\u79CD hacky \u7684\u7F13\u5B58\u6E05\u9664\u65B9\u5F0F\u3002\\n\\n### Q14: \u5982\u4F55\u5BFC\u5165 JSON \u6587\u4EF6\uFF1F\\n\\n- **Node.js 17.5+ (\u9700\u8981 `--experimental-json-modules` \u6807\u5FD7) / Node.js 18.20+ (\u7A33\u5B9A)**:\\n  - \u4F7F\u7528 **Import Assertions** (\u5BFC\u5165\u65AD\u8A00):\\n    ```javascript\\n    import packageJson from \'./package.json\' with { type: \'json\' };\\n    console.log(packageJson.version);\\n    ```\\n- **\u65E7\u7248 Node.js \u6216\u4E0D\u4F7F\u7528\u5B9E\u9A8C\u6027\u7279\u6027**: \\\\* \u4F7F\u7528 `fs` \u6A21\u5757\u8BFB\u53D6\u6587\u4EF6\u5E76\u624B\u52A8\u89E3\u6790\uFF1A\\n\\n  ````javascript\\n  import fs from \'node:fs/promises\';\\n\\n          const packageJsonContent = await fs.readFile(\'./package.json\', \'utf8\');\\n          const packageJson = JSON.parse(packageJsonContent);\\n          console.log(packageJson.version);\\n          ```\\n\\n  **\u524D\u7AEF\u8865\u5145**\uFF1A\u73B0\u4EE3\u524D\u7AEF\u6784\u5EFA\u5DE5\u5177\uFF08Webpack, Vite, Rollup \u7B49\uFF09\u901A\u5E38\u5185\u7F6E\u4E86\u5BF9 JSON \u5BFC\u5165\u7684\u652F\u6301\uFF0C\u4F60\u53EF\u4EE5\u5728\u4EE3\u7801\u4E2D\u76F4\u63A5 `import data from \'./data.json\';`\uFF0C\u6784\u5EFA\u5DE5\u5177\u4F1A\u8D1F\u8D23\u5904\u7406\u3002Import Assertions \u662F\u66F4\u6807\u51C6\u5316\u7684\u65B9\u5F0F\uFF0C\u672A\u6765\u53EF\u80FD\u4F1A\u88AB\u6784\u5EFA\u5DE5\u5177\u66F4\u5E7F\u6CDB\u5730\u539F\u751F\u652F\u6301\u3002\\n  ````\\n\\n### Q15: \u4F55\u65F6\u4F7F\u7528\u9ED8\u8BA4\u5BFC\u51FA (default export) vs \u547D\u540D\u5BFC\u51FA (named exports)\uFF1F\\n\\n\u8FD9\u662F\u4E00\u4E2A\u98CE\u683C\u548C\u5B9E\u8DF5\u95EE\u9898\uFF0C\u4F5C\u8005\u7ED9\u51FA\u4E86\u4ED6\u7684\u5EFA\u8BAE\uFF1A\\n\\n- **\u9ED8\u8BA4\u5BFC\u51FA (`export default`)**:\\n\\n  - \u9002\u7528\u4E8E\u4E00\u4E2A\u6A21\u5757\u4E3B\u8981\u5BFC\u51FA\u4E00\u4E2A**\u6838\u5FC3**\u529F\u80FD\u3001\u7C7B\u6216\u5BF9\u8C61\u65F6\u3002\\n  - \u4F8B\u5982\uFF1A\u4E00\u4E2A `left-pad` \u5E93\u4E3B\u8981\u5C31\u662F\u90A3\u4E2A\u586B\u5145\u51FD\u6570\u3002\\n  - \u53EF\u4EE5\u4E0E\u547D\u540D\u5BFC\u51FA\u7ED3\u5408\u4F7F\u7528\uFF1A\\n\\n    ```javascript\\n    // read-json.js\\n    export default function readJson() {\\n      /* ... */\\n    }\\n    export class JSONError extends Error {\\n      /* ... */\\n    }\\n\\n    // usage.js\\n    import readJson, { JSONError } from \\"read-json\\";\\n    ```\\n\\n- **\u547D\u540D\u5BFC\u51FA (`export { ... }` \u6216 `export const/function/class ...`)**:\\n\\n  - **\u591A\u4E2A\u4E3B\u8981 API**: \u5982\u679C\u4E00\u4E2A\u5305\u63D0\u4F9B\u591A\u4E2A\u540C\u7B49\u91CD\u8981\u7684\u529F\u80FD\uFF0C\u7279\u522B\u662F\u5305\u542B\u540C\u6B65\u548C\u5F02\u6B65\u7248\u672C\u65F6\uFF0C\u4F7F\u7528\u547D\u540D\u5BFC\u51FA\u66F4\u6E05\u6670\u3002\\n\\n    ```javascript\\n    // read-json.js\\n    export function readJson() {\\n      /* async */\\n    }\\n    export function readJsonSync() {\\n      /* sync */\\n    }\\n\\n    // usage.js\\n    import { readJson, readJsonSync } from \\"read-json\\"; // \u6E05\u6670\u533A\u5206\\n    ```\\n\\n  - **\u907F\u514D\u6A21\u7CCA\u547D\u540D**: \u907F\u514D\u4F7F\u7528\u8FC7\u4E8E\u901A\u7528\u7684\u540D\u79F0\u4F5C\u4E3A\u547D\u540D\u5BFC\u51FA\uFF0C\u8FD9\u4F1A\u8FEB\u4F7F\u6D88\u8D39\u8005\u91CD\u547D\u540D\u4EE5\u9632\u51B2\u7A81\u3002\\n\\n    ```javascript\\n    // \u274C \u4E0D\u597D\u7684\u4F8B\u5B50: parse-json.js\\n    // export function parse() { ... }\\n\\n    // \u6D88\u8D39\u8005\u9700\u8981\u91CD\u547D\u540D\\n    // import { parse as parseJson } from \'parse-json\';\\n\\n    // \u2705 \u597D\u7684\u4F8B\u5B50: parse-json.js\\n    export function parseJson() { ... }\\n\\n    // \u6D88\u8D39\u8005\u76F4\u63A5\u4F7F\u7528\\n    import { parseJson } from \'parse-json\';\\n    ```\\n\\n  - **\u53D6\u4EE3\u547D\u540D\u7A7A\u95F4\u6A21\u5F0F**: ESM \u4E2D\uFF0C\u503E\u5411\u4E8E\u4F7F\u7528\u63CF\u8FF0\u6027\u7684\u547D\u540D\u5BFC\u51FA\uFF0C\u800C\u4E0D\u662F\u50CF CommonJS \u90A3\u6837\u5BFC\u51FA\u4E00\u4E2A\u5305\u542B\u591A\u4E2A\u65B9\u6CD5\u7684\u5BF9\u8C61\uFF08\u547D\u540D\u7A7A\u95F4\uFF09\u3002\\n\\n    ```javascript\\n    // CommonJS (\u65E7)\\n    // const isStream = require(\'is-stream\');\\n    // isStream.writable(stream);\\n\\n    // ESM (\u63A8\u8350)\\n    // is-stream.js\\n    // export function isStream() { ... }\\n    // export function isReadableStream() { ... }\\n    // export function isWritableStream() { ... }\\n\\n    // usage.js\\n    import { isWritableStream } from \\"is-stream\\";\\n    isWritableStream(stream);\\n    ```\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1A\\n\\n- **Tree Shaking**: \u547D\u540D\u5BFC\u51FA\u901A\u5E38\u5BF9 Tree Shaking \u66F4\u53CB\u597D\u3002\u6784\u5EFA\u5DE5\u5177\u80FD\u66F4\u5BB9\u6613\u5730\u9759\u6001\u5206\u6790\u51FA\u54EA\u4E9B\u547D\u540D\u5BFC\u51FA\u88AB\u4F7F\u7528\u4E86\uFF0C\u4ECE\u800C\u79FB\u9664\u672A\u4F7F\u7528\u7684\u4EE3\u7801\u3002\u9ED8\u8BA4\u5BFC\u51FA\u5982\u679C\u662F\u5BF9\u8C61\u6216\u7C7B\uFF0C\u5176\u5185\u90E8\u65B9\u6CD5\u7684\u6447\u6811\u4F18\u5316\u53EF\u80FD\u9700\u8981\u66F4\u590D\u6742\u7684\u5206\u6790\u6216\u7279\u5B9A\u5199\u6CD5\u3002\\n- **\u7EC4\u4EF6\u5E93**: \u5927\u578B\u7EC4\u4EF6\u5E93\u901A\u5E38\u4F7F\u7528\u547D\u540D\u5BFC\u51FA\u6765\u5BFC\u51FA\u5404\u4E2A\u7EC4\u4EF6\uFF0C\u65B9\u4FBF\u7528\u6237\u6309\u9700\u5BFC\u5165\uFF1A`import { Button, Modal } from \'my-ui-library\';`\u3002\\n- **\u53EF\u8BFB\u6027\u4E0E\u53EF\u53D1\u73B0\u6027**: \u547D\u540D\u5BFC\u51FA\u4F7F\u5F97\u6A21\u5757\u63D0\u4F9B\u7684\u529F\u80FD\u66F4\u52A0\u4E00\u76EE\u4E86\u7136\uFF0CIDE \u4E5F\u80FD\u63D0\u4F9B\u66F4\u597D\u7684\u81EA\u52A8\u8865\u5168\u63D0\u793A\u3002\\n\\n---\\n\\n## \u603B\u7ED3\\n\\n\u8F6C\u5411 Pure ESM \u662F JavaScript \u751F\u6001\u7CFB\u7EDF\u53D1\u5C55\u7684\u5FC5\u7136\u8D8B\u52BF\u3002\u867D\u7136\u77ED\u671F\u5185\u4F1A\u7ED9\u4F7F\u7528 CommonJS \u7684\u9879\u76EE\u5E26\u6765\u4E00\u4E9B\u6311\u6218\uFF0C\u4F46\u7406\u89E3 ESM \u7684\u57FA\u672C\u539F\u7406\u3001\u638C\u63E1\u8FC1\u79FB\u6B65\u9AA4\u548C\u89E3\u51B3\u5E38\u89C1\u95EE\u9898\u7684\u7B56\u7565\u81F3\u5173\u91CD\u8981\u3002\u79EF\u6781\u62E5\u62B1 ESM \u4E0D\u4EC5\u80FD\u8BA9\u4F60\u4F7F\u7528\u6700\u65B0\u7684\u5E93\u548C\u5DE5\u5177\uFF0C\u8FD8\u80FD\u4EAB\u53D7\u5230\u6A21\u5757\u6807\u51C6\u5316\u3001\u6027\u80FD\u4F18\u5316\uFF08\u5982\u66F4\u597D\u7684 Tree Shaking\uFF09\u548C\u4E0E\u6D4F\u89C8\u5668\u73AF\u5883\u66F4\u4E00\u81F4\u7684\u5F00\u53D1\u4F53\u9A8C\u3002\u5BF9\u4E8E\u524D\u7AEF\u5F00\u53D1\u8005\u800C\u8A00\uFF0C\u719F\u6089 ESM \u66F4\u662F\u73B0\u4EE3 Web \u5F00\u53D1\u7684\u57FA\u7840\u3002"}]}}')}}]);